insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr & Greek yogurt bowl with berries', 'Skyr- og jógúrtskál með berjum', 'Skyr is strained, so one bowl carries the protein of a chicken breast with almost no fat. Greek yogurt adds creaminess and fat that keep you full longer, and both bring live cultures that support a diverse gut microbiome. Berries supply polyphenols and fibre with very little sugar, and walnuts and flax add plant omega-3.', 'breakfast', array['150 g plain skyr (hreint)', '100 g organic Greek yogurt (e.g. Bíóbú, hrein)', '100 g frozen blueberries or raspberries, thawed overnight', '15 g walnuts, roughly chopped', '1 tbsp ground flaxseed', 'Cinnamon to taste']::text[], array['Stir skyr and Greek yogurt together. The yogurt makes it creamy, the skyr keeps protein high.', 'Top with the berries and their juice, walnuts, flaxseed and cinnamon. No honey or sugar needed.']::text[], 5, 1, 423, 28, 27, 24, NULL, '{"why": "Skyr is strained, so one bowl carries the protein of a chicken breast with almost no fat. Greek yogurt adds creaminess and fat that keep you full longer, and both bring live cultures that support a diverse gut microbiome. Berries supply polyphenols and fibre with very little sugar, and walnuts and flax add plant omega-3.", "highlights": ["28 g protein", "Live cultures", "Plant omega-3"], "tip": "Thaw a portion of frozen berries in a jar overnight: by morning they make their own sauce.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F4F3EE", "c": [["#6A2F5A", "dots", 0.35], ["#8A6A45", "crumble", 0.2], ["#B59B6A", "crumble", 0.1]]}, "source_id": "b1", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chia pudding with Greek yogurt & berries', 'Chiagrautur með grískri jógúrt', 'Chia seeds absorb about ten times their weight in liquid and form a gel that slows digestion, which smooths the blood sugar curve after breakfast. Each jar has around 10 g of fibre that feeds gut bacteria, which in turn produce anti-inflammatory short-chain fatty acids. Skyr lifts the protein so it holds you until lunch.', 'breakfast', array['100 g chia seeds', '400 ml lactose-free whole milk', '300 g organic Greek yogurt', '400 g plain skyr', '320 g frozen blueberries, raspberries or strawberries', '40 g pumpkin seeds', 'Cinnamon, vanilla, pinch of salt']::text[], array['Whisk chia, milk, cinnamon, vanilla and salt. Wait 5 minutes and whisk again so the seeds don''t clump.', 'Stir in the skyr and Greek yogurt and divide between 4 jars.', 'Top each jar with 80 g frozen berries straight from the bag; they thaw into a sauce overnight.', 'Refrigerate at least 4 hours. Add pumpkin seeds when you eat it so they stay crunchy.']::text[], 10, 4, 440, 28, 33, 24, array['meal-prep']::text[], '{"why": "Chia seeds absorb about ten times their weight in liquid and form a gel that slows digestion, which smooths the blood sugar curve after breakfast. Each jar has around 10 g of fibre that feeds gut bacteria, which in turn produce anti-inflammatory short-chain fatty acids. Skyr lifts the protein so it holds you until lunch.", "highlights": ["Fibre", "Plant omega-3", "Steady energy"], "tip": "Make 4 jars on Sunday and breakfast is done until Thursday. The skyr lifts protein to about 27 g a jar.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "jar", "base": "#E9E4D6", "c": [["#7E2F4F", "dots", 0.35], ["#5B6B4A", "dots", 0.1], ["#D8D2C2", "dots", 0.3]]}, "source_id": "b2", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Spinach & pepper egg muffins', 'Eggjamúffur', 'Eggs are one of the richest sources of choline, which the brain and liver depend on, plus lutein for the eyes. With almost no carbohydrate, this breakfast keeps insulin low and energy steady all morning. Parmesan adds protein and a savoury depth. Having them ready in the fridge removes the excuse to grab a pastry.', 'breakfast', array['10 eggs', '100 g spinach, chopped', '1 red pepper, diced', 'Green parts of 3 spring onions', '60 g grated cheese', '40 g parmesan, grated', '10 g butter for the tin', 'Salt, pepper, smoked paprika']::text[], array['Heat the oven to 180 °C. Butter a 12-hole muffin tin well.', 'Divide spinach, pepper and spring onion greens between the holes.', 'Whisk eggs with salt, pepper, paprika and the parmesan, pour over the vegetables and top with the grated cheese.', 'Bake 20–22 minutes until just set. Cool, then refrigerate in a sealed box.']::text[], 30, 4, 344, 28, 5, 23, array['meal-prep']::text[], '{"why": "Eggs are one of the richest sources of choline, which the brain and liver depend on, plus lutein for the eyes. With almost no carbohydrate, this breakfast keeps insulin low and energy steady all morning. Parmesan adds protein and a savoury depth. Having them ready in the fridge removes the excuse to grab a pastry.", "highlights": ["Choline", "Low carb", "Grab-and-go"], "tip": "Eat cold on the go or reheat 30 seconds. Pair with raw cucumber and half an avocado.", "fodmap_note": null, "serving_note": "3 muffins", "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#E8C25A", "balls", 0.55], ["#3E7B3A", "leaves", 0.2], ["#C8402E", "cubes", 0.15]]}, "source_id": "b3", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sweet potato & egg hash', 'Sætkartöflu- og eggjapanna', 'Sweet potato is one of the best sources of beta-carotene, which the body turns into vitamin A for skin, vision and immune defence. The fat from eggs and butter helps you absorb it. Eggs and parmesan supply complete protein with every essential amino acid.', 'breakfast', array['300 g roasted sweet potato (from prep)', '6 eggs', 'Spring onion greens, sliced', '100 g spinach', '15 g butter', '20 g parmesan to finish', 'Salt, pepper, chili flakes']::text[], array['Melt butter in a pan and crisp the roasted sweet potato for 5 minutes.', 'Wilt in the spinach and spring onion greens, then make 6 hollows and crack in the eggs.', 'Cover and cook 4–5 minutes until the whites set but the yolks still run. Grate parmesan over, season and serve.']::text[], 15, 2, 562, 31, 42, 30, NULL, '{"why": "Sweet potato is one of the best sources of beta-carotene, which the body turns into vitamin A for skin, vision and immune defence. The fat from eggs and butter helps you absorb it. Eggs and parmesan supply complete protein with every essential amino acid.", "highlights": ["Vitamin A", "Complete protein", "Fibre"], "tip": "This is what Sunday''s sweet potato tray is for: breakfast in 15 minutes.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p1"], "makes": [], "illustration": {"v": "skillet", "c": [["#E07A2F", "cubes", 0.4], ["#F6F1E4", "wedge", 0.35], ["#3E7B3A", "leaves", 0.15]]}, "source_id": "b4", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Soft-boiled eggs on homemade toast', 'Linsoðin egg á heimabökuðu brauði', 'A soft yolk keeps its nutrients intact: vitamin D, B12, choline and selenium. Avocado adds monounsaturated fat and potassium, and raw vegetables add crunch, water and fibre for very few calories. Homemade sourdough is long-fermented, which makes it easier to digest than supermarket bread.', 'breakfast', array['2 slices homemade spelt sourdough (from prep)', '10 g butter', '3 eggs', '½ avocado', 'Raw cucumber', 'Raw carrot sticks', 'Flaky sea salt, black pepper, chili flakes']::text[], array['Lower eggs straight from the fridge into boiling water. Cook 6½ minutes for a jammy yolk, then 30 seconds in cold water.', 'Toast the bread and butter it while hot.', 'Peel the eggs (or serve in cups) and season with flaky salt and pepper.', 'Serve with sliced avocado and raw cucumber and carrot on the side.']::text[], 10, 1, 659, 32, 53, 36, NULL, '{"why": "A soft yolk keeps its nutrients intact: vitamin D, B12, choline and selenium. Avocado adds monounsaturated fat and potassium, and raw vegetables add crunch, water and fibre for very few calories. Homemade sourdough is long-fermented, which makes it easier to digest than supermarket bread.", "highlights": ["Choline", "Healthy fats", "Raw crunch"], "tip": "Slice the loaf before freezing and toast straight from frozen. Avoid Icelandic rúgbrauð for daily use: most versions contain a lot of sugar.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p6"], "makes": [], "illustration": {"v": "board", "c": [["#B98A55", "slices", 0.3], ["#F6F1E4", "wedge", 0.3], ["#7FA34A", "slices", 0.15], ["#E58A2E", "strands", 0.15]]}, "source_id": "b5", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Protein hafragrautur', 'Prótein-hafragrautur', 'Oats contain beta-glucan, a soluble fibre shown to lower LDL cholesterol and slow the rise in blood sugar. Stirring in skyr turns a carb-heavy classic into a balanced meal. A warm breakfast also feels more filling on dark winter mornings.', 'breakfast', array['120 g rolled oats', '500 ml lactose-free whole milk', '200 g plain skyr', '120 g frozen blueberries or raspberries', '10 g butter', 'Pinch of salt, cinnamon']::text[], array['Bring milk, oats and salt to a simmer and cook 4–5 minutes, stirring.', 'Take off the heat and stir in the skyr (off the heat so it stays creamy).', 'Top with berries, a knob of butter and cinnamon.']::text[], 10, 2, 516, 28, 64, 18, array['meal-prep']::text[], '{"why": "Oats contain beta-glucan, a soluble fibre shown to lower LDL cholesterol and slow the rise in blood sugar. Stirring in skyr turns a carb-heavy classic into a balanced meal. A warm breakfast also feels more filling on dark winter mornings.", "highlights": ["Beta-glucan", "Warming", "28 g protein"], "tip": "Classic Icelandic porridge with the protein of a skyr bowl. It reheats with a splash of milk.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#E6D9BC", "c": [["#6A2F5A", "dots", 0.3], ["#F2C94C", "smooth", 0.08]]}, "source_id": "b6", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Shakshuka with Icelandic tomatoes', 'Shakshuka', 'Cooking tomatoes releases lycopene, an antioxidant that is absorbed much better when heated with fat. Red peppers are among the richest sources of vitamin C. Three eggs give a solid protein base, and the sauce alone counts as two portions of vegetables.', 'breakfast', array['2 tbsp avocado oil', 'Green part of 1 leek, sliced', '2 red peppers, sliced', '1 garlic clove', '800 g canned tomatoes (tomatoes + salt only)', '9 eggs (3 per serving)', '90 g feta', 'Cumin, paprika, chili, parsley']::text[], array['Soften leek greens and pepper in avocado oil for 8 minutes. Add garlic and spices for 1 minute.', 'Add tomatoes and simmer 12–15 minutes until thick. This sauce is your 3-day base.', 'Per serving: heat ⅓ of the sauce in a small pan, crack in 3 eggs, cover and cook 5–6 minutes.', 'Crumble feta and parsley over the top. Good with a slice of homemade toast.']::text[], 30, 3, 518, 31, 24, 33, array['meal-prep']::text[], '{"why": "Cooking tomatoes releases lycopene, an antioxidant that is absorbed much better when heated with fat. Red peppers are among the richest sources of vitamin C. Three eggs give a solid protein base, and the sauce alone counts as two portions of vegetables.", "highlights": ["Lycopene", "Vitamin C", "Complete protein"], "tip": "Swap in fresh tomatoes from Flúðir or Hveragerði in summer.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "skillet", "base": "#B8392A", "c": [["#F6F1E4", "wedge", 0.4], ["#F4F3EE", "crumble", 0.12], ["#3E7B3A", "leaves", 0.08]]}, "source_id": "b7", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Kotasæla oat pancakes', 'Kotasælupönnukökur', 'Kotasæla is rich in casein, a slow-digesting protein that keeps you full for hours. Blended oats replace white flour and keep their fibre, and a banana sweetens without added sugar. It feels like a treat yet has close to 30 g of protein.', 'breakfast', array['150 g oats', '300 g kotasæla (cottage cheese)', '4 eggs', '1 small firm banana (just yellow, not spotty)', '20 g butter for the pan', '150 g frozen blueberries or raspberries, warmed', 'Cinnamon, pinch of salt, ½ tsp baking powder']::text[], array['Blend oats, kotasæla, eggs, banana, cinnamon, salt and baking powder until smooth. Rest 5 minutes.', 'Fry small pancakes in butter over medium heat, about 2 minutes per side.', 'Serve with warmed berries. Cool leftovers and stack with baking paper between them.']::text[], 20, 3, 504, 29, 51, 20, array['meal-prep']::text[], '{"why": "Kotasæla is rich in casein, a slow-digesting protein that keeps you full for hours. Blended oats replace white flour and keep their fibre, and a banana sweetens without added sugar. It feels like a treat yet has close to 30 g of protein.", "highlights": ["Casein protein", "No added sugar", "Kid-friendly"], "tip": "Reheat in a dry pan or the toaster.", "fodmap_note": null, "serving_note": "4 small pancakes + berries", "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#D9A75C", "balls", 0.5], ["#7E2F4F", "dots", 0.25]]}, "source_id": "b8", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Green skyr smoothie', 'Grænn skyrþeytingur', 'The fastest way to 40 g of protein. Spinach adds folate and magnesium without changing the taste, and frozen berries are frozen at peak ripeness, so their polyphenols are well preserved. Oats and peanut butter slow digestion, so it won''t spike blood sugar like a juice.', 'breakfast', array['250 g plain skyr', '100 g frozen blueberries or strawberries', 'Handful of spinach', '30 g oats', '1 tbsp peanut butter (100% peanuts)', '150 ml lactose-free milk or water']::text[], array['Blend everything until smooth, about 45 seconds.', 'Frozen berries make it cold and thick without ice.']::text[], 5, 1, 515, 42, 54, 16, NULL, '{"why": "The fastest way to 40 g of protein. Spinach adds folate and magnesium without changing the taste, and frozen berries are frozen at peak ripeness, so their polyphenols are well preserved. Oats and peanut butter slow digestion, so it won''t spike blood sugar like a juice.", "highlights": ["42 g protein", "Polyphenols", "2 minutes"], "tip": "No protein powder needed: skyr carries 27 g of protein on its own.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#7C9A4E", "c": []}, "source_id": "b9", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Lamb & egg breakfast skillet', 'Lambakjöts- og eggjapanna', 'Red meat provides heme iron, which the body absorbs far better than iron from plants, plus B12 and zinc for energy and immunity. Icelandic lamb grazes freely on grass all summer, giving it a better fat profile than grain-fed meat. Kale adds vitamin K and calcium.', 'breakfast', array['150 g pulled lamb (leftover)', '200 g roasted sweet potato (from prep)', '4 eggs', '80 g kale, shredded', '10 g butter', 'Chives, chili flakes']::text[], array['Crisp lamb and sweet potato in butter for 5 minutes.', 'Add kale and cook until it softens.', 'Make 4 hollows, crack in the eggs, cover and cook 4–5 minutes. Finish with chives.']::text[], 15, 2, 563, 38, 29, 33, NULL, '{"why": "Red meat provides heme iron, which the body absorbs far better than iron from plants, plus B12 and zinc for energy and immunity. Icelandic lamb grazes freely on grass all summer, giving it a better fat profile than grain-fed meat. Kale adds vitamin K and calcium.", "highlights": ["Iron & B12", "Zinc", "Leftover hero"], "tip": "A Monday breakfast made from Sunday''s roast.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p1", "d4"], "makes": [], "illustration": {"v": "skillet", "c": [["#7A4A35", "strands", 0.3], ["#E07A2F", "cubes", 0.25], ["#F6F1E4", "wedge", 0.25], ["#2F5E35", "leaves", 0.15]]}, "source_id": "b10", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Salmon & sweet potato bowl with tzatziki', 'Laxaskál með sætkartöflum', 'Salmon''s omega-3 fats help the body resolve inflammation and support heart and brain health; two portions of oily fish a week is the standard recommendation. Sweet potato gives slow-release energy for the afternoon, and tzatziki adds live cultures and protein.', 'lunch', array['130 g salmon (leftover from dinner)', '150 g roasted sweet potato', 'Handful of greens', 'Raw cucumber', 'Raw carrot, ribboned', '80 g tzatziki', '1 tbsp pumpkin seeds']::text[], array['Pack greens, cucumber and carrot at the bottom of a lunch box, then sweet potato and salmon.', 'Eat the salmon cold or at room temperature. Reheating dries it out; warm only the sweet potato if you like.', 'Keep tzatziki in a small pot and add with the pumpkin seeds just before eating.']::text[], 5, 1, 639, 42, 52, 29, array['meal-prep']::text[], '{"why": "Salmon''s omega-3 fats help the body resolve inflammation and support heart and brain health; two portions of oily fish a week is the standard recommendation. Sweet potato gives slow-release energy for the afternoon, and tzatziki adds live cultures and protein.", "highlights": ["Omega-3", "Vitamin D", "Gut-friendly"], "tip": "Made entirely from leftovers: zero cooking on the day.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["p1", "d5", "p4"], "makes": [], "illustration": {"v": "bowl", "c": [["#EE8C6C", "fillet", 0.3], ["#E07A2F", "cubes", 0.3], ["#6E9E3E", "leaves", 0.2], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "l1", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Pulled lamb & rice bowl', 'Lambaskál með hrísgrjónum', 'White rice is one of the gentlest carbohydrates for the gut and refills muscle glycogen well after training. Lamb adds heme iron, zinc and B12, and roasted root vegetables bring fibre and beta-carotene.', 'lunch', array['120 g pulled lamb', '160 g cooked white rice', '150 g roasted rófur, carrots & parsnip', 'Kale, massaged with lemon', '70 g tzatziki']::text[], array['Layer rice, roasted roots and lamb in a box. Reheat until steaming hot, about 2 minutes.', 'Top with kale and add tzatziki just before eating.']::text[], 5, 1, 737, 42, 69, 32, array['meal-prep']::text[], '{"why": "White rice is one of the gentlest carbohydrates for the gut and refills muscle glycogen well after training. Lamb adds heme iron, zinc and B12, and roasted root vegetables bring fibre and beta-carotene.", "highlights": ["Iron & B12", "Easy to digest", "Recovery"], "tip": "Icelandic lamb from the slow roast is fatty enough to stay juicy on day 3.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["d4", "p3", "p5", "p4"], "makes": [], "illustration": {"v": "bowl", "c": [["#7A4A35", "strands", 0.3], ["#F4F1E8", "dots", 0.3], ["#E39A3B", "cubes", 0.2], ["#2F5E35", "leaves", 0.12]]}, "source_id": "l2", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken, rice & crunchy raw veg box', 'Kjúklingabox með hrásalati', 'Chicken thigh is a complete protein with more iron and zinc than breast, and it stays juicy when reheated. Raw carrot and cucumber add water, fibre and crunch. Chewing slows you down, which helps you notice when you''re full.', 'lunch', array['140 g cooked chicken thigh, sliced', '160 g cooked white rice', 'Raw carrot sticks', 'Raw cucumber sticks', '80 g tzatziki', 'Lemon wedge, dill']::text[], array['Pack rice and chicken in one compartment; reheat that part until steaming.', 'Keep carrot and cucumber in a cold compartment and tzatziki in a small pot.', 'Dip the raw veg in tzatziki and squeeze lemon over the chicken.']::text[], 5, 1, 585, 46, 60, 17, array['meal-prep']::text[], '{"why": "Chicken thigh is a complete protein with more iron and zinc than breast, and it stays juicy when reheated. Raw carrot and cucumber add water, fibre and crunch. Chewing slows you down, which helps you notice when you''re full.", "highlights": ["46 g protein", "Raw crunch", "Simple"], "tip": "The simplest Lifeline lunch: protein, one carb, raw crunch and a yogurt sauce.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["d6", "p3", "p4"], "makes": [], "illustration": {"v": "box", "c": [["#C99A5B", "fillet", 0.3], ["#F4F1E8", "dots", 0.25], ["#E58A2E", "strands", 0.15], ["#93B957", "slices", 0.15], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "l3", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Icelandic fish soup', 'Fiskisúpa', 'Cod and haddock are very lean protein and among the best sources of iodine, which the thyroid needs to regulate metabolism. Soup is hydrating and filling for its calories, so it suits a lighter lunch.', 'lunch', array['30 g butter', 'Green parts of 2 leeks', '3 carrots', '1 red pepper', '1 garlic clove', '2 tbsp tomato paste', '400 g canned tomatoes', '200 ml cream', '500 g cod (þorskur)', '500 g haddock (ýsa)', '1 L water or homemade fish stock, 1 tsp curry powder, salt, parsley']::text[], array['Melt butter and soften leek greens, carrot, pepper and garlic for 10 minutes.', 'Stir in curry powder and tomato paste, then add tomatoes and 1 L water or stock. Simmer 15 minutes.', 'Add cream. Cut fish into chunks, add, and poach gently 4–5 minutes. Do not boil hard.', 'Cool quickly and portion into 5 containers.']::text[], 40, 5, 415, 38, 18, 21, array['meal-prep', 'freezer']::text[], '{"why": "Cod and haddock are very lean protein and among the best sources of iodine, which the thyroid needs to regulate metabolism. Soup is hydrating and filling for its calories, so it suits a lighter lunch.", "highlights": ["Lean protein", "Iodine", "Hydrating"], "tip": "Reheat gently to just below a simmer so the fish stays tender. Most stock cubes contain onion powder, sugar and additives; homemade stock or water is better.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "soupbowl", "base": "#E58B4E", "c": [["#F6F1E4", "chunks", 0.5], ["#E39A3B", "cubes", 0.2], ["#3E7B3A", "leaves", 0.05]]}, "source_id": "l4", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr-tuna stuffed sweet potato', 'Fyllt sætkartafla með túnfiski', 'Canned tuna is one of the cheapest complete proteins you can buy. Swapping mayonnaise for skyr turns a fatty filling into a protein-rich one. Sweet potato adds fibre, potassium and vitamin A.', 'lunch', array['1 small roasted sweet potato (≈150 g)', '1 can tuna in water, drained', '60 g skyr (instead of mayo)', 'Chives or spring onion greens', 'Cucumber, diced', 'Squeeze of lemon, dill', 'Side of greens', '1 tsp extra-virgin olive oil']::text[], array['Mix tuna, skyr, chives, cucumber, lemon, dill, salt and pepper.', 'Split the sweet potato and warm it if you like.', 'Spoon in the tuna filling and serve with greens dressed in olive oil.']::text[], 10, 1, 436, 41, 44, 10, array['meal-prep']::text[], '{"why": "Canned tuna is one of the cheapest complete proteins you can buy. Swapping mayonnaise for skyr turns a fatty filling into a protein-rich one. Sweet potato adds fibre, potassium and vitamin A.", "highlights": ["41 g protein", "Low fat", "Budget"], "tip": "Store-bought mayonnaise is mostly rapeseed oil. Skyr does the same job with 10× the protein.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["p1"], "makes": [], "illustration": {"v": "plate", "c": [["#E07A2F", "fillet", 0.4], ["#D8D1BF", "crumble", 0.25], ["#6E9E3E", "leaves", 0.25]]}, "source_id": "l5", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Egg, sweet potato & feta salad', 'Eggja- og sætkartöflusalat', 'Eggs, sweet potato and spinach together cover a wide range of micronutrients: choline, beta-carotene, folate and iron. Olive oil in the dressing helps you absorb the fat-soluble vitamins in the vegetables.', 'lunch', array['3 hard-boiled eggs (from prep)', '150 g roasted sweet potato', 'Spinach', 'Raw cucumber', '30 g feta', '2 tsp extra-virgin olive oil', 'Lemon juice, a little mustard']::text[], array['Whisk olive oil, lemon, mustard, salt and pepper in the base of a box.', 'Add sweet potato and cucumber and toss.', 'Top with spinach, halved eggs and crumbled feta.']::text[], 5, 1, 646, 32, 45, 38, array['meal-prep']::text[], '{"why": "Eggs, sweet potato and spinach together cover a wide range of micronutrients: choline, beta-carotene, folate and iron. Olive oil in the dressing helps you absorb the fat-soluble vitamins in the vegetables.", "highlights": ["Choline", "Vitamin A", "Make-ahead"], "tip": "Unpeeled boiled eggs keep a full week in the fridge.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p1", "p2"], "makes": [], "illustration": {"v": "bowl", "c": [["#F6F1E4", "wedge", 0.3], ["#E07A2F", "cubes", 0.25], ["#F4F3EE", "crumble", 0.12], ["#3E7B3A", "leaves", 0.2]]}, "source_id": "l6", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smoked salmon & avocado rice bowl', 'Hrísgrjónaskál með reyktum laxi', 'Smoked salmon delivers marine omega-3s and vitamin D with no cooking. Avocado adds monounsaturated fat and potassium, and white rice keeps it easy on the stomach. Ideal for busy days.', 'lunch', array['170 g cooked white rice', '100 g smoked salmon', '1 soft- or hard-boiled egg', '½ avocado', 'Raw cucumber', 'Raw carrot, julienned', '2 tsp tamari', 'Lime or lemon, spring onion greens']::text[], array['Reheat the rice until steaming, then let it cool a little (or eat it at room temperature).', 'Top with smoked salmon, halved egg, avocado, cucumber and carrot.', 'Dress with tamari, lime and sliced spring onion greens.']::text[], 10, 1, 599, 36, 61, 24, array['meal-prep']::text[], '{"why": "Smoked salmon delivers marine omega-3s and vitamin D with no cooking. Avocado adds monounsaturated fat and potassium, and white rice keeps it easy on the stomach. Ideal for busy days.", "highlights": ["Omega-3", "Vitamin D", "Gentle carbs"], "tip": "Pack the avocado whole and slice it at lunch so it stays green.", "fodmap_note": null, "serving_note": null, "keeps_days": 1, "meal_prep": true, "freezer": false, "uses_prep": ["p3"], "makes": [], "illustration": {"v": "bowl", "c": [["#F4F1E8", "dots", 0.3], ["#EE8C6C", "fillet", 0.25], ["#8DB255", "slices", 0.15], ["#F6F1E4", "wedge", 0.1], ["#E58A2E", "strands", 0.1]]}, "source_id": "l7", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken & rice soup with ginger', 'Kjúklingasúpa með engifer', 'Ginger has well-documented anti-nausea and mild anti-inflammatory effects. Warm broth with tender chicken and rice is one of the easiest meals to digest, which makes it ideal when the stomach feels unsettled. Each bowl still delivers close to 40 g of protein.', 'lunch', array['20 g butter', 'Green parts of 2 leeks', '3 carrots', '1 garlic clove', 'Thumb of ginger', '900 g boneless chicken thighs', '150 g white rice (dry)', '150 g spinach', 'Juice of 1 lemon', '1.8 L water, bay leaf, thyme, salt, pepper']::text[], array['Soften leek greens, carrot, garlic and ginger in butter for 8 minutes.', 'Add whole chicken thighs, water, bay and thyme. Simmer 25 minutes, then lift out the chicken and shred it.', 'Add the rice and simmer 12 minutes. Return the chicken, stir in spinach and lemon, and season well.', 'Portion into 5 containers. The rice thickens it overnight; add a splash of water when reheating.']::text[], 45, 5, 426, 39, 36, 14, array['meal-prep', 'freezer']::text[], '{"why": "Ginger has well-documented anti-nausea and mild anti-inflammatory effects. Warm broth with tender chicken and rice is one of the easiest meals to digest, which makes it ideal when the stomach feels unsettled. Each bowl still delivers close to 40 g of protein.", "highlights": ["Ginger", "Gut-gentle", "39 g protein"], "tip": "Comforting, gentle on the stomach, and freezes in single portions.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "soupbowl", "base": "#E9CF8A", "c": [["#D7B484", "strands", 0.35], ["#E39A3B", "cubes", 0.2], ["#F4F1E8", "dots", 0.15], ["#3E7B3A", "leaves", 0.1]]}, "source_id": "l8", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Mexican chicken rice bowl with guacamole', 'Mexíkósk kjúklingaskál', 'Homemade guacamole gives you healthy fats without the additives in shop versions. Fresh salsa adds vitamin C, which helps you absorb iron from the meal. Skyr instead of sour cream adds protein and cuts fat.', 'lunch', array['140 g cooked chicken thigh', '150 g cooked white rice', '70 g homemade guacamole', 'Tomato salsa', 'Lime, coriander', '50 g skyr (instead of sour cream)', 'Shredded lettuce', '15 g grated cheese']::text[], array['Chop tomato and coriander with lime and salt for a quick salsa.', 'Season the chicken with cumin and smoked paprika; pack it with rice and reheat until steaming.', 'Add lettuce, salsa, guacamole, skyr and cheese just before eating.']::text[], 5, 1, 661, 51, 56, 26, array['meal-prep']::text[], '{"why": "Homemade guacamole gives you healthy fats without the additives in shop versions. Fresh salsa adds vitamin C, which helps you absorb iron from the meal. Skyr instead of sour cream adds protein and cuts fat.", "highlights": ["51 g protein", "Healthy fats", "Vitamin C"], "tip": "Press cling film onto the guacamole surface so it stays green until lunch.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p3", "d6"], "makes": [], "illustration": {"v": "bowl", "c": [["#C99A5B", "strands", 0.25], ["#F4F1E8", "dots", 0.2], ["#8DB255", "smooth", 0.15], ["#D6493A", "cubes", 0.12], ["#6E9E3E", "leaves", 0.1]]}, "source_id": "l9", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Beef wrap lunch box', 'Nautavefja í nesti', 'Fast food can be real food. Organic beef provides heme iron, zinc, B12 and creatine. Homemade wraps avoid the emulsifiers and seed oils in shop wraps, and raw vegetable sticks add crunch and fibre.', 'lunch', array['1 portion seasoned beef, wraps, cheese, guacamole & tzatziki (leftover)', 'Raw carrot sticks', 'Raw cucumber sticks']::text[], array['Pack the beef in a reheatable container, wraps and cheese separately, guacamole and tzatziki in small pots.', 'At lunch, warm the beef until steaming, then assemble the wraps.', 'Eat the raw veg on the side, dipped in the tzatziki.']::text[], 5, 1, 783, 44, 55, 43, array['meal-prep']::text[], '{"why": "Fast food can be real food. Organic beef provides heme iron, zinc, B12 and creatine. Homemade wraps avoid the emulsifiers and seed oils in shop wraps, and raw vegetable sticks add crunch and fibre.", "highlights": ["Iron & B12", "Creatine", "Real fast food"], "tip": "Wraps stay soft if you warm them for 10 seconds with the beef.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["d7"], "makes": [], "illustration": {"v": "board", "c": [["#E2C9A0", "slices", 0.35], ["#6A2A1E", "crumble", 0.25], ["#8DB255", "smooth", 0.12], ["#E58A2E", "strands", 0.15]]}, "source_id": "l10", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Restaurant-style cod with sweet potato purée', 'Þorskur dagsins', 'Cod is one of the leanest proteins there is and rich in iodine, selenium and B12. Searing in avocado oil and basting in butter gives restaurant flavour while keeping the fish moist. Sweet potato purée adds beta-carotene and fibre.', 'dinner', array['2 thick cod loins (≈180 g each)', '1 tbsp avocado oil', '40 g butter (20 g for basting, 15 g for the purée, 5 g sauce)', '1 garlic clove, lightly crushed', '½ lemon', '400 g sweet potato', 'Tenderstem or broccoli florets', 'Thyme, flaky sea salt, white pepper, nutmeg, parsley']::text[], array['Salt the cod all over and leave it on a rack in the fridge for 15–30 minutes. This firms the flakes like in a restaurant. Pat it completely dry.', 'Boil peeled sweet potato 15 minutes, drain well and blend with 15 g butter, salt and a pinch of nutmeg until silky.', 'Heat avocado oil in a heavy pan until shimmering. Lay the cod in, presentation side down, and leave it for 3–4 minutes until golden.', 'Flip, add 20 g butter, garlic and thyme, and baste for 1–2 minutes. Take it off at 50–52 °C in the centre, when it is still just translucent, and rest 2 minutes.', 'Steam the broccoli for 3 minutes. Swirl the last butter and the lemon into the pan juices and spoon over the fish.']::text[], 35, 2, 578, 39, 50, 26, NULL, '{"why": "Cod is one of the leanest proteins there is and rich in iodine, selenium and B12. Searing in avocado oil and basting in butter gives restaurant flavour while keeping the fish moist. Sweet potato purée adds beta-carotene and fibre.", "highlights": ["Lean protein", "Iodine & selenium", "Restaurant quality"], "tip": "Use the thickest loin cut and don''t move the fish while it sears. In Icelandic restaurants this is ''fiskur dagsins''; ask the fishmonger for the day''s catch.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F3E3C0", "fillet", 0.3], ["#E8913A", "smooth", 0.3], ["#2F6E35", "leaves", 0.25]]}, "source_id": "d1", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Kjötsúpa — Icelandic lamb soup', 'Kjötsúpa', 'Simmering lamb on the bone releases collagen and minerals into the broth. Rófur and carrots are hardy Icelandic vegetables with vitamin C and fibre. A traditional dish that is whole-food by nature and perfect for batch cooking.', 'dinner', array['1.2 kg lamb soup meat on the bone (≈900 g meat)', '600 g rófur', '400 g potatoes', '400 g carrots', 'Green parts of 2 leeks', 'A small wedge of white cabbage', '50 g white rice', '2.5 L water, salt, pepper, dried thyme and parsley']::text[], array['Cover the lamb with 2.5 L cold water, bring to the boil and skim off the foam.', 'Add rice, herbs and salt. Simmer 45 minutes.', 'Add rófur, potatoes, carrots and leek greens in chunks; simmer 20 minutes. Add cabbage for the last 10.', 'Lift out the meat, remove the bones and return the meat to the pot.']::text[], 90, 6, 522, 30, 38, 28, array['meal-prep', 'freezer']::text[], '{"why": "Simmering lamb on the bone releases collagen and minerals into the broth. Rófur and carrots are hardy Icelandic vegetables with vitamin C and fibre. A traditional dish that is whole-food by nature and perfect for batch cooking.", "highlights": ["Collagen", "Root vegetables", "Tradition"], "tip": "Chill overnight and lift off the fat layer if you want it leaner. Kjötsúpa tastes better on day two. Packaged ''súpujurtir'' often contain dried onion; use plain dried herbs.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "soupbowl", "base": "#C9A46A", "c": [["#7A4A35", "chunks", 0.3], ["#E39A3B", "cubes", 0.25], ["#EDE0B0", "cubes", 0.2], ["#9CBF6E", "leaves", 0.1]]}, "source_id": "d2", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Plokkfiskur gratin', 'Plokkfiskur', 'Iceland''s classic fish dish, made here without flour: just fish, potatoes, butter and milk. It is an easy way to reach two fish meals a week, with iodine-rich lean protein that is gentle on digestion.', 'dinner', array['600 g haddock or cod', '600 g potatoes, boiled', 'Green parts of 1–2 leeks, finely sliced', '50 g butter', '300 ml lactose-free whole milk', '60 g grated cheese', 'Cucumber', 'Tomatoes', 'Salt, white pepper, chives']::text[], array['Poach the fish in salted water 5 minutes; drain and flake. Peel and roughly break the boiled potatoes.', 'Soften the leek greens in butter for 6 minutes, add milk and warm through (no flour needed).', 'Fold in fish and potatoes and season with plenty of white pepper and chives.', 'Spread in an ovenproof dish, top with cheese and grill 5–8 minutes. Serve with cucumber-tomato salad.']::text[], 40, 4, 451, 35, 37, 18, array['meal-prep']::text[], '{"why": "Iceland''s classic fish dish, made here without flour: just fish, potatoes, butter and milk. It is an easy way to reach two fish meals a week, with iodine-rich lean protein that is gentle on digestion.", "highlights": ["Lean protein", "Iodine", "Comfort food"], "tip": "The traditional dish uses onion; leek greens and chives give the same mild flavour without the bloating.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#EFE2B8", "crumble", 0.55], ["#D6493A", "slices", 0.15], ["#93B957", "slices", 0.15]]}, "source_id": "d3", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Slow-roast lamb shoulder with root veg', 'Hægeldaður lambabógur', 'Slow cooking turns the shoulder''s collagen into gelatin, making a cheaper cut melt in the mouth. Grass-fed Icelandic lamb provides heme iron, zinc and B12, and the leftovers feed lunches and breakfasts for days.', 'dinner', array['1.2 kg boneless lamb shoulder (or 2 kg on the bone)', '2 garlic cloves, sliced', '600 g rófur', '600 g carrots', '300 g parsnips', '2 tbsp avocado oil', '300 g tzatziki, with mint added', 'Rosemary, thyme, salt']::text[], array['Make small cuts in the lamb, push in the garlic slices, and rub with salt and rosemary. Roast covered at 150 °C for 3½ hours.', 'Toss rófur, carrots and parsnips in avocado oil and thyme. Roast alongside, uncovered, for the last 60 minutes at 200 °C.', 'Rest the lamb 15 minutes, then pull apart with two forks.', 'Stir chopped mint into the tzatziki and serve on the side.']::text[], 240, 6, 680, 40, 30, 45, array['meal-prep', 'freezer']::text[], '{"why": "Slow cooking turns the shoulder''s collagen into gelatin, making a cheaper cut melt in the mouth. Grass-fed Icelandic lamb provides heme iron, zinc and B12, and the leftovers feed lunches and breakfasts for days.", "highlights": ["Iron & zinc", "Grass-fed", "Feeds the week"], "tip": "Icelandic lamb grazes free all summer. Roast a big shoulder and the leftovers feed lunch bowls and breakfast skillets.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": ["Pulled lamb for lunch bowls and breakfast skillets"], "illustration": {"v": "plate", "c": [["#7A4A35", "strands", 0.4], ["#E39A3B", "cubes", 0.25], ["#EBDDB8", "cubes", 0.12], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "d4", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Juicy salmon with sweet potato & broccoli', 'Safaríkur lax með sætkartöflum', 'Gentle cooking protects salmon''s delicate omega-3 fats and keeps it moist. Broccoli contains sulforaphane, which switches on the body''s own antioxidant defences. A complete anti-inflammatory plate.', 'dinner', array['600 g salmon or arctic char (bleikja), thick centre cut', '600 g sweet potato, cubed', '120 g white rice (dry)', '400 g broccoli florets (skip the stalks)', '2 tbsp avocado oil', '10 g butter', '1 lemon', '1 garlic clove', '200 g tzatziki with extra dill']::text[], array['Roast sweet potato in avocado oil and salt at 210 °C for 20 minutes. Add broccoli for the last 10.', 'Meanwhile, take the salmon out of the fridge, salt it and pat dry.', 'Turn the oven down to 140 °C. Put the salmon on a separate small tray with butter, garlic and lemon zest, and bake 12–15 minutes.', 'Take it out at 48–50 °C in the centre, when the flakes just separate and the middle is still glossy. It keeps cooking on the plate.', 'Cook the rice. Pack 2 portions for tomorrow before serving with tzatziki and lemon.']::text[], 40, 4, 718, 41, 63, 33, array['meal-prep']::text[], '{"why": "Gentle cooking protects salmon''s delicate omega-3 fats and keeps it moist. Broccoli contains sulforaphane, which switches on the body''s own antioxidant defences. A complete anti-inflammatory plate.", "highlights": ["Omega-3", "Vitamin D", "Sulforaphane"], "tip": "Low oven, short time, thermometer: that''s the whole secret to salmon that isn''t dry. A thin line of white albumin on top means you went past it.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["2 dinners + 2 salmon lunch bowls"], "illustration": {"v": "tray", "c": [["#EE8C6C", "fillet", 0.35], ["#E07A2F", "cubes", 0.3], ["#2F6E35", "leaves", 0.25]]}, "source_id": "d5", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('One-pan lemon chicken with sweet potato', 'Kjúklingur á einni pönnu', 'One pan, four portions. Peppers and broccoli are rich in vitamin C, and sweet potato and carrots in beta-carotene. Thigh meat stays moist for days, which makes it ideal for packed lunches.', 'dinner', array['1 kg boneless chicken thighs', '600 g sweet potato', '3 carrots', '2 peppers', 'Broccoli', '2 tbsp avocado oil', '1 lemon', '1 garlic clove, grated', 'Oregano, smoked paprika, salt']::text[], array['Toss chicken with half the avocado oil, lemon, garlic, oregano, paprika and salt. Marinate 10 minutes or overnight.', 'Spread sweet potato and carrots in a large roasting pan with the rest of the oil and roast 15 minutes at 200 °C.', 'Add chicken, pepper and broccoli. Roast 25 minutes until the chicken reaches 75 °C.', 'Slice the extra thighs for lunches while still warm.']::text[], 50, 4, 591, 53, 45, 22, array['meal-prep']::text[], '{"why": "One pan, four portions. Peppers and broccoli are rich in vitamin C, and sweet potato and carrots in beta-carotene. Thigh meat stays moist for days, which makes it ideal for packed lunches.", "highlights": ["53 g protein", "Vitamin C", "One pan"], "tip": "Thighs stay juicy for days; breasts dry out when reheated. Serve with white rice instead of sweet potato for variety.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["Cooked chicken for lunch boxes and bowls"], "illustration": {"v": "tray", "c": [["#C99A5B", "fillet", 0.35], ["#E07A2F", "cubes", 0.2], ["#E39A3B", "cubes", 0.12], ["#C8402E", "slices", 0.1], ["#2F6E35", "leaves", 0.12]]}, "source_id": "d6", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Organic beef wraps with guacamole & tzatziki', 'Nautavefjur með guacamole', 'Organic beef supplies heme iron, zinc, B12 and creatine, which supports strength training. Guacamole and tzatziki replace sugary sauces and sour cream with healthy fats and protein.', 'dinner', array['600 g organic beef mince', '2 tsp avocado oil', '2 tbsp tomato paste', '8 small homemade wraps (≈45 g each)', '60 g grated cheese', 'Homemade guacamole: 2 avocados, lime, tomato, chives, salt', '200 g tzatziki', 'Shredded lettuce', 'Cumin, smoked paprika, oregano, chili, 1 small garlic clove, salt']::text[], array['Wraps: rub 40 g butter into 250 g flour with 1 tsp salt, add 150 ml warm water and knead 2 minutes. Rest 15 minutes, roll 8 thin rounds and cook in a dry hot pan, 40 seconds per side.', 'Brown the beef in avocado oil over high heat, breaking it up. Add spices, garlic and tomato paste with a splash of water and cook 5 minutes.', 'Guacamole: mash avocado with lime, salt, chopped tomato and chives.', 'Fill warm wraps with beef, cheese, lettuce, guacamole and tzatziki.']::text[], 35, 4, 738, 43, 44, 43, array['meal-prep']::text[], '{"why": "Organic beef supplies heme iron, zinc, B12 and creatine, which supports strength training. Guacamole and tzatziki replace sugary sauces and sour cream with healthy fats and protein.", "highlights": ["Iron & B12", "Creatine", "Family favourite"], "tip": "Most shop wraps contain emulsifiers, preservatives and rapeseed oil. Homemade takes 15 minutes and they freeze well. For sensitive stomachs, use 100% corn tortillas (masa, water, lime): low FODMAP and naturally wheat-free. The Wraps tab has five more options, including the viral cottage cheese wrap.", "fodmap_note": null, "serving_note": "2 wraps", "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["2 beef wrap lunch boxes"], "illustration": {"v": "board", "c": [["#E2C9A0", "slices", 0.35], ["#6A2A1E", "crumble", 0.25], ["#8DB255", "smooth", 0.15], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "d7", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Kjötbollur in tomato sauce with rice', 'Kjötbollur í tómatsósu', 'Oats replace breadcrumbs, and parmesan in the mix adds protein and savoury depth. The tomato sauce provides lycopene, which is absorbed better when cooked with fat. A family-friendly dinner that freezes well.', 'dinner', array['600 g organic beef mince', '1 egg', 'Spring onion greens, finely chopped', '40 g oats (instead of breadcrumbs)', '40 g parmesan, grated', '1 garlic clove', '800 g canned tomatoes', '1½ tbsp avocado oil', '240 g white rice (dry)', 'Spinach or green salad on the side', 'Salt, pepper, basil, oregano']::text[], array['Mix beef, egg, spring onion greens, oats, parmesan, grated garlic and seasoning. Roll about 20 meatballs.', 'Brown in avocado oil, add tomatoes and basil, and simmer covered for 20 minutes.', 'Cook the rice. Serve with spinach or a green salad.', 'Cool rice quickly and pack it separately from the meatballs.']::text[], 45, 4, 719, 43, 66, 30, array['meal-prep', 'freezer']::text[], '{"why": "Oats replace breadcrumbs, and parmesan in the mix adds protein and savoury depth. The tomato sauce provides lycopene, which is absorbed better when cooked with fat. A family-friendly dinner that freezes well.", "highlights": ["Iron", "Lycopene", "Parmesan boost"], "tip": "Oats replace breadcrumbs, which usually contain sugar and seed oil. The original version served this with cauliflower mash (butter, milk, nutmeg); rice is gentler on the gut.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F4F1E8", "dots", 0.3], ["#8A3B26", "balls", 0.35], ["#C23A2B", "smooth", 0.15], ["#3E7B3A", "leaves", 0.1]]}, "source_id": "d8", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Homemade fiskibollur', 'Heimagerðar fiskibollur', 'Homemade fish balls are almost pure fish, unlike shop versions bulked out with starch and seed oil. Haddock is lean, mild and rich in iodine and B12, and children usually love them.', 'dinner', array['700 g haddock', 'Spring onion greens or chives', '1 egg', '60 g oats, blended to flour', '100 ml lactose-free milk', '40 g butter for frying', '240 g white rice (dry), or potatoes', '200 g tzatziki', 'Cucumber salad', 'Salt, white pepper, nutmeg']::text[], array['Blend fish, spring onion greens, egg, oat flour, milk, salt, pepper and nutmeg into a thick farce. Chill 15 minutes.', 'Shape with two spoons and fry in butter over medium heat, 4 minutes per side.', 'Serve with rice, tzatziki and a cucumber salad.']::text[], 40, 4, 569, 41, 63, 16, array['meal-prep', 'freezer']::text[], '{"why": "Homemade fish balls are almost pure fish, unlike shop versions bulked out with starch and seed oil. Haddock is lean, mild and rich in iodine and B12, and children usually love them.", "highlights": ["Lean protein", "Iodine", "No fillers"], "tip": "Shop fiskibollur are often bound with wheat flour, potato starch and rapeseed oil. These take 15 minutes of hands-on time and are good cold in a lunch box.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#D9B36C", "balls", 0.4], ["#F4F1E8", "dots", 0.25], ["#F4F3EE", "smooth", 0.1], ["#93B957", "slices", 0.15]]}, "source_id": "d9", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken & vegetable curry', 'Kjúklingakarrí', 'Turmeric and ginger contain anti-inflammatory compounds, and cooking turmeric with fat and black pepper improves absorption of its curcumin. Coconut milk makes it rich without cream, and each portion hides several vegetables.', 'dinner', array['1 kg boneless chicken thighs', '400 ml coconut milk (coconut + water only)', '400 g canned tomatoes', 'Green parts of 1–2 leeks', '2 garlic cloves', 'Thumb of ginger', '2 peppers', '2 carrots', '1 zucchini', '150 g spinach', '20 g butter or ghee', '300 g white rice (dry)', 'Garam masala, turmeric, cumin, chili, salt']::text[], array['Fry leek greens in butter 5 minutes; add garlic, ginger and spices for 1 minute.', 'Add chicken pieces and brown lightly. Add tomatoes, coconut milk and carrots.', 'Simmer 20 minutes, add pepper and zucchini for the last 8, and stir through spinach at the end.', 'Cook rice. Cool both quickly and portion into 6 boxes.']::text[], 45, 6, 628, 40, 57, 27, array['meal-prep', 'freezer']::text[], '{"why": "Turmeric and ginger contain anti-inflammatory compounds, and cooking turmeric with fat and black pepper improves absorption of its curcumin. Coconut milk makes it rich without cream, and each portion hides several vegetables.", "highlights": ["Turmeric & ginger", "Hidden vegetables", "Batch"], "tip": "Many coconut milks and curry pastes contain gums, sugar and onion. Use spices and coconut milk with coconut and water only.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#E0A33A", "c": [["#C99A5B", "chunks", 0.35], ["#F4F1E8", "dots", 0.25], ["#2F6E35", "leaves", 0.1], ["#C8402E", "slices", 0.08]]}, "source_id": "d10", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Harðfiskur with butter', 'Harðfiskur með smjöri', 'Wind-dried fish is Iceland''s original protein snack: about 80 g of protein per 100 g with nothing added. Butter makes it more satisfying and turns it into a proper snack.', 'snack', array['30 g harðfiskur (dried haddock or wolffish)', '10 g Icelandic butter']::text[], array['Spread butter on the harðfiskur pieces and eat.']::text[], 1, 1, 180, 25, 0, 9, array['meal-prep']::text[], '{"why": "Wind-dried fish is Iceland''s original protein snack: about 80 g of protein per 100 g with nothing added. Butter makes it more satisfying and turns it into a proper snack.", "highlights": ["80% protein", "Zero additives", "Icelandic"], "tip": "Around 80% protein: the original Icelandic protein bar, with no additives. Keeps for weeks in the bag.", "fodmap_note": null, "serving_note": null, "keeps_days": 30, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E5D3A5", "slices", 0.6], ["#F2D56B", "smooth", 0.12]]}, "source_id": "s1", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Eggs, raw veg & tzatziki box', 'Egg, hrátt grænmeti og tzatziki', 'Protein from eggs and yogurt plus crunchy raw vegetables keeps hunger away far better than a sweet snack. Chewing raw vegetables also slows you down.', 'snack', array['2 boiled eggs', 'Raw carrot sticks', 'Raw cucumber sticks', '100 g tzatziki', 'Flaky sea salt, pepper']::text[], array['Pack eggs, carrot and cucumber sticks and a pot of tzatziki. Dip and eat.']::text[], 2, 1, 323, 24, 18, 17, array['meal-prep']::text[], '{"why": "Protein from eggs and yogurt plus crunchy raw vegetables keeps hunger away far better than a sweet snack. Chewing raw vegetables also slows you down.", "highlights": ["Protein", "Fibre", "Crunch"], "tip": "Uses eggs and tzatziki from the Sunday prep.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p2", "p4"], "makes": [], "illustration": {"v": "box", "c": [["#F6F1E4", "wedge", 0.3], ["#F4F3EE", "smooth", 0.2], ["#93B957", "slices", 0.2], ["#E58A2E", "strands", 0.2]]}, "source_id": "s2", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr bowl with blueberries & walnuts', 'Skyrskál með bláberjum', 'Skyr is Iceland''s own high-protein dairy, strained so thick it is closer to a soft cheese than a yogurt. Blueberries carry anthocyanins, pigments linked to better memory and healthier blood vessels. Walnuts are the nut highest in plant omega-3.', 'breakfast', array['250 g plain skyr (hreint)', '80 g blueberries (fresh or frozen)', '15 g walnuts, roughly chopped', '1 tbsp ground flaxseed', 'Cinnamon to taste']::text[], array['Spoon the skyr into a bowl. Loosen with a splash of water if you like it thinner.', 'Top with blueberries, walnuts, flaxseed and cinnamon. No honey or sugar needed: the berries do the work.']::text[], 5, 1, 355, 32, 27, 15, NULL, '{"why": "Skyr is Iceland''s own high-protein dairy, strained so thick it is closer to a soft cheese than a yogurt. Blueberries carry anthocyanins, pigments linked to better memory and healthier blood vessels. Walnuts are the nut highest in plant omega-3.", "highlights": ["32 g protein", "Low fat", "Anthocyanins"], "tip": "Wild Icelandic bláber from August picking freeze well. Keep a bag in the freezer all winter.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F4F3EE", "c": [["#3D4A7A", "dots", 0.35], ["#8A6A45", "crumble", 0.2], ["#B59B6A", "crumble", 0.1]]}, "source_id": "b11", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Overnight oats with skyr & chia', 'Hafrar yfir nótt', 'Soaking oats overnight softens them and makes them easier to digest. Their beta-glucan supports healthy cholesterol and steady blood sugar. Skyr and chia make it a balanced meal rather than just a bowl of carbs.', 'breakfast', array['200 g rolled oats', '600 g plain skyr', '400 ml lactose-free whole milk', '40 g chia seeds', '320 g frozen blueberries or raspberries', 'Cinnamon, pinch of salt']::text[], array['Mix oats, skyr, milk, chia, cinnamon and salt in a large bowl.', 'Divide between 4 jars and top each with 80 g berries.', 'Refrigerate overnight. Eat cold, or warm one jar for 90 seconds.']::text[], 10, 4, 437, 29, 59, 11, array['meal-prep']::text[], '{"why": "Soaking oats overnight softens them and makes them easier to digest. Their beta-glucan supports healthy cholesterol and steady blood sugar. Skyr and chia make it a balanced meal rather than just a bowl of carbs.", "highlights": ["Beta-glucan", "Made ahead", "Fibre"], "tip": "Make 4 jars on Sunday and breakfast is done until Thursday.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "jar", "base": "#E9E1CF", "c": [["#7E2F4F", "dots", 0.35], ["#CDBB97", "crumble", 0.3]]}, "source_id": "b12", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sourdough with smoked salmon & eggs', 'Súrdeigsbrauð með reyktum laxi', 'Salmon is one of the few foods with meaningful vitamin D, which most people in Iceland lack in winter, plus the marine omega-3s EPA and DHA that help the body regulate inflammation. With two eggs it becomes a breakfast with close to 40 g of protein.', 'breakfast', array['1 slice spelt sourdough', '80 g smoked salmon', '2 eggs, soft-boiled', '¼–½ avocado', 'Cucumber slices', '5 g butter', 'Dill, lemon, black pepper']::text[], array['Boil the eggs 6½ minutes, then cool in cold water and peel.', 'Toast and butter the bread. Layer avocado, salmon and cucumber.', 'Halve the eggs on top and finish with dill, lemon and pepper.']::text[], 10, 1, 573, 39, 36, 31, NULL, '{"why": "Salmon is one of the few foods with meaningful vitamin D, which most people in Iceland lack in winter, plus the marine omega-3s EPA and DHA that help the body regulate inflammation. With two eggs it becomes a breakfast with close to 40 g of protein.", "highlights": ["Omega-3", "Vitamin D", "39 g protein"], "tip": "Avoid Icelandic rúgbrauð for daily use: most versions contain a lot of sugar.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p6"], "makes": [], "illustration": {"v": "board", "c": [["#B98A55", "slices", 0.3], ["#EE8C6C", "fillet", 0.3], ["#F6F1E4", "wedge", 0.2], ["#7FA34A", "slices", 0.15]]}, "source_id": "b13", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Pulled lamb & barley bowl', 'Lambaskál með byggi', 'Icelandic barley is a whole grain with plenty of fibre, including beta-glucan, which supports healthy cholesterol and blood sugar. Lamb adds iron and B12. Barley is high in fructans, so check the gut note if you bloat easily.', 'lunch', array['120 g pulled lamb', '150 g cooked Icelandic barley (bygg)', '150 g roasted rófur, carrots & parsnip', 'Kale, massaged with lemon', '50 g tzatziki or skyr-mint dressing']::text[], array['Layer barley, roasted roots and lamb in a box.', 'Top with kale. Reheat 90 seconds or eat at room temperature.', 'Add dressing just before eating.']::text[], 5, 1, 694, 40, 66, 31, array['meal-prep']::text[], '{"why": "Icelandic barley is a whole grain with plenty of fibre, including beta-glucan, which supports healthy cholesterol and blood sugar. Lamb adds iron and B12. Barley is high in fructans, so check the gut note if you bloat easily.", "highlights": ["Whole grain", "Local barley", "Iron"], "tip": "Byggið from Vallanes is grown in Iceland and keeps its bite for 4 days.", "fodmap_note": "Barley is high in fructans. For a gentler version use white rice (see the pulled lamb & rice bowl).", "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["d4", "p5", "p4"], "makes": [], "illustration": {"v": "bowl", "c": [["#7A4A35", "strands", 0.3], ["#D9C7A0", "dots", 0.3], ["#E39A3B", "cubes", 0.2], ["#2F5E35", "leaves", 0.15]]}, "source_id": "l11", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken & quinoa jar salad', 'Kjúklinga- og kínóasalat í krukku', 'Quinoa is one of the few plant foods with all essential amino acids, and it is rich in magnesium, which supports sleep and muscle function. Olive oil, olives and feta give it a Mediterranean fat profile linked to lower inflammation.', 'lunch', array['130 g cooked chicken thigh, sliced', '150 g cooked quinoa', 'Cucumber', 'Cherry tomatoes', 'Chives or spring onion greens', '30 g feta', 'A few olives', '2 tsp extra-virgin olive oil', 'Lemon juice, oregano']::text[], array['Shake olive oil, lemon, oregano and salt in the bottom of a large jar.', 'Layer in order: cucumber, tomato, quinoa, chicken, feta, olives, chives.', 'Seal and refrigerate. Tip into a bowl to eat.']::text[], 5, 1, 639, 45, 42, 32, array['meal-prep']::text[], '{"why": "Quinoa is one of the few plant foods with all essential amino acids, and it is rich in magnesium, which supports sleep and muscle function. Olive oil, olives and feta give it a Mediterranean fat profile linked to lower inflammation.", "highlights": ["Complete plant protein", "Magnesium", "Mediterranean"], "tip": "Dressing at the bottom, greens and protein on top: nothing goes soggy for 3 days. Quinoa is low FODMAP.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["d6"], "makes": [], "illustration": {"v": "jar", "base": "#EAD9A8", "c": [["#C99A5B", "strands", 0.3], ["#D6493A", "balls", 0.2], ["#93B957", "cubes", 0.2], ["#F4F3EE", "crumble", 0.1]]}, "source_id": "l12", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Egg, chickpea & roast root salad', 'Eggja- og kjúklingabaunasalat', 'Chickpeas feed beneficial gut bacteria with prebiotic fibre and add plant protein. Combined with eggs they make a high-protein vegetarian lunch. Legumes can cause bloating in sensitive people; see the gut note.', 'lunch', array['3 hard-boiled eggs (from prep)', '120 g canned chickpeas, rinsed well', '150 g roasted roots', 'Spinach or greens', '2 tsp extra-virgin olive oil', 'Lemon juice, mustard', '20 g feta']::text[], array['Whisk olive oil, lemon, a little mustard, salt and pepper in the base of a box.', 'Add chickpeas and roasted roots and toss.', 'Top with greens, halved eggs and feta.']::text[], 5, 1, 692, 37, 50, 39, array['meal-prep']::text[], '{"why": "Chickpeas feed beneficial gut bacteria with prebiotic fibre and add plant protein. Combined with eggs they make a high-protein vegetarian lunch. Legumes can cause bloating in sensitive people; see the gut note.", "highlights": ["Fibre", "Plant protein", "Prebiotic"], "tip": "Unpeeled boiled eggs keep a full week in the fridge.", "fodmap_note": "Chickpeas are high in GOS. Rinsed canned chickpeas up to about 40 g are better tolerated; or swap them for roasted sweet potato.", "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p2", "p5"], "makes": [], "illustration": {"v": "bowl", "c": [["#F6F1E4", "wedge", 0.3], ["#D9B36C", "balls", 0.25], ["#E39A3B", "cubes", 0.2], ["#3E7B3A", "leaves", 0.2]]}, "source_id": "l13", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smoked salmon potato salad', 'Kartöflusalat með reyktum laxi', 'Cooked and cooled potatoes form resistant starch, which behaves like fibre: it feeds gut bacteria and causes a smaller blood sugar rise than hot potatoes. Smoked salmon adds omega-3 and vitamin D.', 'lunch', array['200 g Icelandic potatoes, boiled and cooled', '100 g smoked salmon', '1 hard-boiled egg', '60 g skyr', 'Chives or spring onion greens', 'Cucumber', 'Lemon, dill, mustard', 'Greens', '1 tsp extra-virgin olive oil']::text[], array['Boil potatoes in their skins (a big pot covers several days), cool and halve.', 'Mix skyr, dill, lemon, mustard, salt and pepper. Fold through potatoes, chives and cucumber.', 'Top with smoked salmon, egg and greens.']::text[], 20, 1, 502, 40, 42, 20, array['meal-prep']::text[], '{"why": "Cooked and cooled potatoes form resistant starch, which behaves like fibre: it feeds gut bacteria and causes a smaller blood sugar rise than hot potatoes. Smoked salmon adds omega-3 and vitamin D.", "highlights": ["Resistant starch", "Omega-3", "Gut-friendly"], "tip": "Potatoes are low FODMAP, and cooled potatoes form resistant starch, which is kinder to blood sugar than hot mash.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#E9D9A6", "balls", 0.35], ["#EE8C6C", "fillet", 0.25], ["#F6F1E4", "wedge", 0.15], ["#6E9E3E", "leaves", 0.2]]}, "source_id": "l14", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Red lentil soup with egg & skyr', 'Rauð linsubaunasúpa', 'Lentils are rich in fibre, folate and plant iron and cost very little. Skyr and egg lift the protein above 30 g. Lemon juice adds vitamin C, which helps you absorb the iron from the lentils.', 'lunch', array['2 tbsp avocado oil', 'Green parts of 2 leeks', '3 carrots', '1 garlic clove', '350 g red lentils', '400 g canned tomatoes', 'Juice of ½ lemon', '250 g skyr to top (50 g each)', '5 boiled eggs (1 each)', 'Cumin, turmeric, chili, 1.3 L water']::text[], array['Soften leek greens and carrot in avocado oil for 8 minutes; add garlic and spices for 1 minute.', 'Add rinsed lentils, tomatoes and 1.3 L water. Simmer 20 minutes until the lentils collapse.', 'Blend half for a creamy texture, season, and add lemon.', 'Portion into 5 containers. Serve each with a spoon of skyr and a halved boiled egg.']::text[], 35, 5, 477, 32, 59, 13, array['meal-prep', 'freezer']::text[], '{"why": "Lentils are rich in fibre, folate and plant iron and cost very little. Skyr and egg lift the protein above 30 g. Lemon juice adds vitamin C, which helps you absorb the iron from the lentils.", "highlights": ["Fibre", "Folate", "Budget"], "tip": "Lentils alone are lower in protein than meat; the egg and skyr bring each bowl over 30 g.", "fodmap_note": "Lentils contain GOS. Rinsed canned lentils are gentler than dried; keep portions moderate if you bloat easily.", "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "soupbowl", "base": "#D9822B", "c": [["#F4F3EE", "smooth", 0.15], ["#F6F1E4", "wedge", 0.2]]}, "source_id": "l15", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Mexican chicken & sweet potato bowl', 'Mexíkósk kjúklingaskál með sætkartöflum', 'A colourful bowl that covers everything: beans and sweet potato provide fibre and slow carbohydrate, chicken provides the protein, and avocado and lime add healthy fat and vitamin C.', 'lunch', array['130 g cooked chicken thigh', '150 g roasted sweet potato', '80 g kidney beans, rinsed', '¼–½ avocado', 'Tomato salsa', 'Lime juice, coriander', '50 g skyr (instead of sour cream)', 'Shredded lettuce']::text[], array['Chop tomato and coriander with lime and salt for a quick salsa.', 'Pack lettuce, beans, sweet potato and chicken; season the chicken with cumin and smoked paprika.', 'Add avocado, salsa and skyr just before eating.']::text[], 5, 1, 662, 50, 67, 23, array['meal-prep']::text[], '{"why": "A colourful bowl that covers everything: beans and sweet potato provide fibre and slow carbohydrate, chicken provides the protein, and avocado and lime add healthy fat and vitamin C.", "highlights": ["50 g protein", "Fibre", "Vitamin A"], "tip": "Squeeze lime over the avocado so it stays green until lunch.", "fodmap_note": "Kidney beans are high in GOS. Leave them out, or use the rice version of this bowl.", "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p1", "d6"], "makes": [], "illustration": {"v": "bowl", "c": [["#C99A5B", "strands", 0.25], ["#E07A2F", "cubes", 0.2], ["#7A2A2A", "balls", 0.15], ["#8DB255", "slices", 0.15], ["#D6493A", "cubes", 0.1]]}, "source_id": "l16", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chili-stuffed sweet potato', 'Sætkartafla með chili', 'Batch-cooked chili combines beef''s heme iron and B12 with the fibre of beans and tomatoes. Spices like cumin and smoked paprika bring flavour without the sugar and additives of ready-made sauces.', 'lunch', array['1 portion beef & bean chili (leftover, with avocado & skyr)', '150 g roasted sweet potato']::text[], array['Warm the chili and sweet potato separately, 2 minutes each.', 'Split the sweet potato, spoon chili over, top with skyr and avocado.']::text[], 5, 1, 767, 45, 76, 32, array['meal-prep']::text[], '{"why": "Batch-cooked chili combines beef''s heme iron and B12 with the fibre of beans and tomatoes. Spices like cumin and smoked paprika bring flavour without the sugar and additives of ready-made sauces.", "highlights": ["Iron", "Fibre", "Freezer-friendly"], "tip": "Freeze chili in single portions; take one out the night before.", "fodmap_note": "Contains kidney beans from the chili. Make the chili without beans for a gentler version.", "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p1", "d12"], "makes": [], "illustration": {"v": "plate", "c": [["#E07A2F", "fillet", 0.35], ["#8E3A23", "crumble", 0.35], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "l17", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Pan-fried cod with brown butter', 'Pönnusteiktur þorskur', 'A quick weeknight dinner of lean, iodine-rich fish. Brown butter gives big flavour from a small amount of fat, and potatoes are naturally low FODMAP and gentle on the gut.', 'dinner', array['2 cod loins (≈180 g each)', '400 g Icelandic potatoes', 'Broccoli florets', '30 g butter', '2 tsp extra-virgin olive oil', '½ lemon, parsley']::text[], array['Boil potatoes 15–18 minutes. Steam broccoli the last 5 minutes and toss with olive oil.', 'Pat the cod dry and salt it. Fry in half the butter over medium-high heat, 3–4 minutes per side.', 'Add the remaining butter and let it foam and turn nutty brown. Add lemon and parsley.', 'Spoon the brown butter over fish and potatoes.']::text[], 25, 2, 498, 40, 43, 19, NULL, '{"why": "A quick weeknight dinner of lean, iodine-rich fish. Brown butter gives big flavour from a small amount of fat, and potatoes are naturally low FODMAP and gentle on the gut.", "highlights": ["Lean protein", "Iodine", "25 minutes"], "tip": "The weeknight version of the restaurant cod. Cook extra potatoes for tomorrow''s smoked salmon potato salad.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F6F1E4", "fillet", 0.35], ["#E9D9A6", "balls", 0.3], ["#2F6E35", "leaves", 0.25]]}, "source_id": "d11", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Beef & bean chili', 'Nautahakks-chili', 'Beef and beans together give heme and plant iron, protein and plenty of fibre. Six portions from one pot make it one of the most time-efficient meals on the list.', 'dinner', array['800 g organic beef mince', '2 cans kidney beans, rinsed', 'Green parts of 2 leeks', '2 peppers', '2 garlic cloves', '800 g canned tomatoes', '1 small tin tomato paste', '1 tbsp avocado oil', '2 avocados to serve', '300 g skyr to serve', 'Cumin, smoked paprika, chili, cinnamon, oregano, salt']::text[], array['Brown the beef in avocado oil in batches. Set aside.', 'Soften leek greens and pepper 8 minutes, add garlic, spices and tomato paste for 2 minutes.', 'Return the beef, add tomatoes and beans. Simmer 30 minutes, lid ajar.', 'Serve with avocado and skyr, over white rice or roasted sweet potato.']::text[], 50, 6, 572, 42, 39, 28, array['meal-prep', 'freezer']::text[], '{"why": "Beef and beans together give heme and plant iron, protein and plenty of fibre. Six portions from one pot make it one of the most time-efficient meals on the list.", "highlights": ["Fibre", "Iron", "6 portions"], "tip": "Check spice blends: many taco mixes contain sugar, onion powder and anti-caking agents. Mix your own.", "fodmap_note": "Kidney beans are high in GOS. For a gentler chili, leave out the beans and add 300 g extra beef or diced sweet potato.", "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": ["Chili-stuffed sweet potato lunches"], "illustration": {"v": "bowl", "base": "#8E3A23", "c": [["#6A2A1E", "crumble", 0.35], ["#7A2A2A", "balls", 0.15], ["#8DB255", "slices", 0.15], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "d12", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Egg & kotasæla snack box', 'Egg og kotasæla', 'Kotasæla is rich in casein, a slowly digested protein, which makes this a good afternoon or evening snack. Eggs add choline and vitamin D.', 'snack', array['2 hard-boiled eggs', '100 g kotasæla', 'Cucumber sticks', 'Cherry tomatoes', 'Salt, pepper, chives']::text[], array['Pack eggs (peeled or not), kotasæla with chives, and the vegetables in a small box.']::text[], 2, 1, 296, 28, 10, 16, array['meal-prep']::text[], '{"why": "Kotasæla is rich in casein, a slowly digested protein, which makes this a good afternoon or evening snack. Eggs add choline and vitamin D.", "highlights": ["Casein", "Choline", "Slow release"], "tip": "Use eggs from the Sunday prep batch.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p2"], "makes": [], "illustration": {"v": "box", "c": [["#F6F1E4", "wedge", 0.3], ["#F4F3EE", "crumble", 0.3], ["#93B957", "slices", 0.2], ["#D6493A", "balls", 0.15]]}, "source_id": "s3", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Restaurant-style French omelette with parmesan', 'Frönsk eggjakaka með parmesan', 'A French omelette is cooked gently, so the eggs stay tender and the yolk''s choline and vitamins A, D and B12 are well preserved. Parmesan is one of the most protein-dense cheeses at about 36 g per 100 g, and its long ageing leaves it almost lactose-free, so it adds flavour and protein without upsetting the stomach.', 'breakfast', array['3 eggs, at room temperature if possible', '10 g butter', '20 g Parmigiano Reggiano, finely grated', 'Chives, finely snipped; black pepper', '1 thin slice sourdough, toasted', 'Handful of greens', 'Raw cucumber', '1 tsp extra-virgin olive oil, lemon']::text[], array['Whisk the eggs with a pinch of salt for a full minute until completely smooth, with no streaks of white. For a silky finish, pass them through a sieve.', 'Heat a 20 cm non-stick pan over medium-low heat. Add two-thirds of the butter and wait until it foams but has no colour.', 'Pour in the eggs. Stir quickly with a silicone spatula while shaking the pan back and forth for 20–30 seconds, until you have very small, soft curds that are still wet.', 'Stop stirring. Smooth into an even layer and let it set for 10–15 seconds. The surface should still look slightly glossy.', 'Sprinkle half the parmesan and chives down the middle. Tilt the pan away from you and roll the omelette over itself towards the edge, then turn it out seam-side down onto a warm plate.', 'Rub the remaining butter over the top for shine and finish with the rest of the parmesan, chives and black pepper. Serve with the toast and lightly dressed greens.']::text[], 10, 1, 567, 35, 24, 36, NULL, '{"why": "A French omelette is cooked gently, so the eggs stay tender and the yolk''s choline and vitamins A, D and B12 are well preserved. Parmesan is one of the most protein-dense cheeses at about 36 g per 100 g, and its long ageing leaves it almost lactose-free, so it adds flavour and protein without upsetting the stomach.", "highlights": ["Choline", "Low carb", "Parmesan protein"], "tip": "The mark of a restaurant omelette is no brown colour at all and a creamy centre. Low heat and constant movement do it. It takes two or three tries to master, and then it''s a 4-minute breakfast.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F3D36E", "fillet", 0.35], ["#F1E7C9", "crumble", 0.12], ["#6E9E3E", "leaves", 0.25], ["#B98A55", "slices", 0.12]]}, "source_id": "b14", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Turkish eggs with paprika butter', 'Tyrknesk egg (çılbır)', 'Yogurt and skyr bring live cultures and extra protein, and eggs bring choline and vitamin D. Paprika butter carries flavour and helps absorb the fat-soluble vitamins. Warm, savoury and gentle on the gut, a strong alternative to a sweet breakfast.', 'breakfast', array['100 g Greek yogurt', '80 g skyr', '½ small garlic clove, grated', '2 very fresh eggs', '15 g butter', '10 g parmesan, grated', '1 slice sourdough, toasted', 'Smoked paprika, chili flakes, dill, lemon, salt']::text[], array['Take yogurt and skyr out of the fridge 15 minutes ahead. Stir together with the garlic, a squeeze of lemon and a pinch of salt, and spread into a shallow bowl.', 'Bring a wide pan of water to a bare simmer. Crack each egg into a small cup first, swirl the water and slide the eggs in. Poach 3 minutes for set whites and runny yolks. Lift out and drain on kitchen paper.', 'Melt the butter until foaming, then take it off the heat and stir in paprika and chili flakes.', 'Set the eggs on the yogurt, spoon over the red butter, and finish with parmesan, dill and toasted sourdough for dipping.']::text[], 15, 1, 649, 40, 38, 37, NULL, '{"why": "Yogurt and skyr bring live cultures and extra protein, and eggs bring choline and vitamin D. Paprika butter carries flavour and helps absorb the fat-soluble vitamins. Warm, savoury and gentle on the gut, a strong alternative to a sweet breakfast.", "highlights": ["Live cultures", "Healthy fats", "Gut-friendly"], "tip": "Very fresh eggs poach neatly with no vinegar needed. Older eggs spread out in the water.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F4F1E8", "c": [["#F6F1E4", "wedge", 0.35], ["#C8402E", "smooth", 0.1], ["#4E7E3A", "leaves", 0.1]]}, "source_id": "b15", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sweet potato, spinach & parmesan frittata', 'Frittata með sætkartöflum og parmesan', 'One pan makes four breakfasts. Eggs, sweet potato and spinach cover protein, beta-carotene, folate and iron, and parmesan adds savoury depth plus extra protein. Cold frittata is also an excellent lunch-box item.', 'breakfast', array['10 eggs', '50 ml lactose-free milk', '300 g roasted sweet potato (from prep)', '150 g spinach', 'Spring onion greens', '60 g parmesan, grated', '15 g butter', 'Salt, pepper, nutmeg']::text[], array['Heat the oven to 190 °C. Melt butter in a 26 cm ovenproof pan and wilt the spinach and spring onion greens.', 'Spread the roasted sweet potato evenly in the pan.', 'Whisk eggs with milk, 40 g parmesan, salt, pepper and nutmeg. Pour over and cook on low heat for 4 minutes until the edges set.', 'Top with the remaining parmesan and bake 12–15 minutes until just set in the middle. Cool and cut into 4 wedges.']::text[], 30, 4, 416, 27, 23, 24, array['meal-prep']::text[], '{"why": "One pan makes four breakfasts. Eggs, sweet potato and spinach cover protein, beta-carotene, folate and iron, and parmesan adds savoury depth plus extra protein. Cold frittata is also an excellent lunch-box item.", "highlights": ["Meal prep", "Vitamin A", "Parmesan protein"], "tip": "Take it out while the centre still wobbles slightly; it firms as it cools and stays tender for days.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": ["p1"], "makes": [], "illustration": {"v": "skillet", "base": "#EFCB62", "c": [["#E07A2F", "cubes", 0.3], ["#3E7B3A", "leaves", 0.2], ["#F1E7C9", "crumble", 0.15]]}, "source_id": "b16", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Cottage cheese egg bites', 'Eggjabitar með kotasælu', 'Blending eggs with kotasæla combines two complete proteins, one fast and one slow-digesting, which keeps you full well into the day. Eggs supply choline and vitamin D. Gentle steam-baking keeps them tender, and they reheat from frozen in a minute.', 'breakfast', array['8 eggs', '250 g kotasæla', '40 g parmesan', '60 g spinach, chopped', '½ red pepper, finely diced', 'Butter for the tin', 'Salt, pepper, chives']::text[], array['Heat the oven to 150 °C and put a roasting tin of hot water on the lowest shelf. The steam is what makes them silky.', 'Blend eggs, kotasæla, parmesan, salt and pepper until completely smooth.', 'Divide spinach, pepper and chives between 12 buttered silicone or muffin cups and pour over the egg mixture.', 'Bake 25–30 minutes until just set with a slight wobble. Cool, then refrigerate or freeze.']::text[], 35, 4, 301, 27, 5, 19, array['meal-prep', 'freezer']::text[], '{"why": "Blending eggs with kotasæla combines two complete proteins, one fast and one slow-digesting, which keeps you full well into the day. Eggs supply choline and vitamin D. Gentle steam-baking keeps them tender, and they reheat from frozen in a minute.", "highlights": ["Choline", "Casein protein", "Freezer-ready"], "tip": "This is the café ''sous-vide egg bite'' made at home: blending in kotasæla makes them velvety and adds a lot of protein.", "fodmap_note": null, "serving_note": "3 bites", "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F0D27A", "balls", 0.55], ["#3E7B3A", "leaves", 0.15], ["#C8402E", "cubes", 0.12]]}, "source_id": "b17", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Cottage cheese flatbread with smoked salmon', 'Kotasæluflatbrauð með reyktum laxi', 'Swapping a flour wrap for one made of kotasæla and egg turns the ''bread'' itself into a protein source. Smoked salmon adds marine omega-3s and vitamin D, and cucumber adds crunch and water. Naturally wheat-free, which is helpful for sensitive guts.', 'breakfast', array['250 g kotasæla', '2 eggs', '120 g smoked salmon', '60 g skyr with dill & lemon', 'Cucumber ribbons', 'Rocket or lettuce', 'Salt, pepper, dried oregano']::text[], array['Heat the oven to 190 °C. Blend kotasæla, eggs, salt and oregano until smooth.', 'Spread thinly into two rounds on baking paper. Bake 30–35 minutes until golden and firm. Cool for 5 minutes and peel off.', 'Spread with dill skyr, add salmon, cucumber and greens, and roll up.']::text[], 40, 2, 334, 39, 8, 16, array['meal-prep']::text[], '{"why": "Swapping a flour wrap for one made of kotasæla and egg turns the ''bread'' itself into a protein source. Smoked salmon adds marine omega-3s and vitamin D, and cucumber adds crunch and water. Naturally wheat-free, which is helpful for sensitive guts.", "highlights": ["Flour-free", "Omega-3", "High protein"], "tip": "The viral two-ingredient ''cottage cheese wrap'': no flour, about 20 g protein per flatbread before filling. Bake a few and keep them in the fridge.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E9C77E", "slices", 0.35], ["#EE8C6C", "fillet", 0.25], ["#93B957", "slices", 0.15], ["#6E9E3E", "leaves", 0.12]]}, "source_id": "b18", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Creamy cottage cheese scrambled eggs', 'Hrærð egg með kotasælu', 'Folding kotasæla into soft eggs adds slow-digesting casein and makes them extra creamy without cream. Eggs bring choline, B12 and vitamin D. A quick breakfast that holds you until lunch.', 'breakfast', array['3 eggs', '80 g kotasæla', '8 g butter', '10 g parmesan', '1 slice sourdough, toasted', 'Cherry tomatoes', 'Chives, black pepper']::text[], array['Whisk eggs with a pinch of salt.', 'Melt butter over low heat, add the eggs and stir slowly with a spatula, pulling the curds in from the edges.', 'When half set, fold in the kotasæla and keep stirring off and on the heat until just creamy.', 'Spoon onto toast and finish with parmesan, chives and black pepper. Tomatoes on the side.']::text[], 8, 1, 575, 41, 32, 31, NULL, '{"why": "Folding kotasæla into soft eggs adds slow-digesting casein and makes them extra creamy without cream. Eggs bring choline, B12 and vitamin D. A quick breakfast that holds you until lunch.", "highlights": ["Choline", "Casein", "Creamy"], "tip": "Take the pan off the heat while the eggs still look slightly underdone. They finish cooking on the plate.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F2D06B", "crumble", 0.4], ["#B98A55", "slices", 0.2], ["#D6493A", "balls", 0.15]]}, "source_id": "b19", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Savoury parmesan oats with jammy egg', 'Saltur hafragrautur með eggi', 'Savoury oats keep the beta-glucan fibre that supports cholesterol and blood sugar, without the sugar most people add to porridge. Eggs and parmesan turn it into a high-protein meal, and spinach adds folate and iron.', 'breakfast', array['50 g rolled oats', '150 ml lactose-free milk + 100 ml water', '20 g parmesan', '2 eggs', 'Handful of spinach', '1 tsp extra-virgin olive oil', 'Chili flakes, black pepper, spring onion greens']::text[], array['Boil eggs 6½ minutes, cool in cold water and peel.', 'Simmer oats in milk, water and a pinch of salt for 4 minutes. Stir in spinach until wilted, then the parmesan.', 'Top with halved eggs, olive oil, chili flakes and spring onion greens.']::text[], 12, 1, 594, 36, 45, 31, NULL, '{"why": "Savoury oats keep the beta-glucan fibre that supports cholesterol and blood sugar, without the sugar most people add to porridge. Eggs and parmesan turn it into a high-protein meal, and spinach adds folate and iron.", "highlights": ["Beta-glucan", "Savoury", "Low sugar"], "tip": "Savoury oats are a creator favourite for good reason: like risotto in 5 minutes, with none of the sugar of sweet porridge.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#E6D9BC", "c": [["#F6F1E4", "wedge", 0.25], ["#3E7B3A", "leaves", 0.15], ["#F1E7C9", "crumble", 0.1]]}, "source_id": "b20", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Blueberry skyr baked oats', 'Bakaðir hafrar með bláberjum', 'Oats, skyr and eggs bake into a balanced breakfast with fibre, protein and fat. Blueberries add anthocyanins, linked to better memory and vascular health. Sweetened only with fruit, so it won''t send blood sugar soaring.', 'breakfast', array['200 g rolled oats', '400 g skyr', '3 eggs', '250 ml lactose-free milk', '1 firm banana, mashed', '250 g frozen blueberries', '30 g walnuts', '1 tsp baking powder, cinnamon, vanilla, pinch of salt']::text[], array['Heat the oven to 180 °C. Mix oats, baking powder, cinnamon and salt.', 'Whisk skyr, eggs, milk, banana and vanilla, then stir in the dry mix and half the blueberries.', 'Pour into a 20 × 25 cm dish, scatter over the rest of the berries and the walnuts.', 'Bake 30–35 minutes until set. Cut into 4 and refrigerate.']::text[], 40, 4, 459, 27, 56, 15, array['meal-prep', 'freezer']::text[], '{"why": "Oats, skyr and eggs bake into a balanced breakfast with fibre, protein and fat. Blueberries add anthocyanins, linked to better memory and vascular health. Sweetened only with fruit, so it won''t send blood sugar soaring.", "highlights": ["Beta-glucan", "Anthocyanins", "Meal prep"], "tip": "Eat cold, or warm a square for 40 seconds with a spoon of skyr on top.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "tray", "c": [["#D9B27A", "crumble", 0.55], ["#3D4A7A", "dots", 0.25], ["#8A6A45", "crumble", 0.1]]}, "source_id": "b21", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Freezer breakfast burritos', 'Morgunburrito í frysti', 'Eggs and beef provide complete protein, heme iron and B12, while sweet potato adds slow carbs and beta-carotene. Having six in the freezer is a real-food alternative to the fast-food breakfast on rushed mornings.', 'breakfast', array['6 homemade wraps (≈60 g each)', '10 eggs', '300 g organic beef mince', '300 g roasted sweet potato (from prep)', '90 g grated cheese', '100 g spinach', '2 tsp avocado oil', 'Cumin, smoked paprika, salt, chives']::text[], array['Brown the beef with cumin, paprika and salt in avocado oil. Set aside.', 'Softly scramble the eggs in the same pan and stir in the spinach.', 'Fill each wrap with egg, beef, sweet potato and cheese. Roll tightly, folding in the sides.', 'Wrap each in baking paper and foil. Freeze. Reheat from frozen: 2 minutes in the microwave, then crisp in a dry pan.']::text[], 40, 6, 534, 32, 38, 28, array['meal-prep', 'freezer']::text[], '{"why": "Eggs and beef provide complete protein, heme iron and B12, while sweet potato adds slow carbs and beta-carotene. Having six in the freezer is a real-food alternative to the fast-food breakfast on rushed mornings.", "highlights": ["Iron & B12", "Complete protein", "Freezer-ready"], "tip": "Six breakfasts ready in the freezer. Corn tortillas work if wheat bothers you.", "fodmap_note": null, "serving_note": "1 burrito", "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E2C9A0", "slices", 0.4], ["#F2D06B", "crumble", 0.2], ["#E07A2F", "cubes", 0.15], ["#6A2A1E", "crumble", 0.1]]}, "source_id": "b22", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Steak & eggs with sweet potato', 'Steik og egg', 'Beef is one of the best sources of heme iron, zinc, B12 and creatine, which supports strength and power. Eggs add choline and sweet potato refills glycogen, making this an ideal plate before or after hard training.', 'breakfast', array['120 g minute steak or sirloin', '2 eggs', '120 g roasted sweet potato', '1 tsp avocado oil', '5 g butter', 'Spinach', 'Flaky sea salt, pepper']::text[], array['Salt the steak. Sear in a very hot pan with avocado oil, 1–2 minutes per side. Rest on a board.', 'Fry the eggs in butter in the same pan and warm the sweet potato alongside.', 'Wilt the spinach in the pan juices, slice the steak and serve together.']::text[], 15, 1, 647, 45, 33, 38, NULL, '{"why": "Beef is one of the best sources of heme iron, zinc, B12 and creatine, which supports strength and power. Eggs add choline and sweet potato refills glycogen, making this an ideal plate before or after hard training.", "highlights": ["Iron & B12", "Creatine", "Training fuel"], "tip": "A weekend breakfast before a long hike or a training session. Ask the butcher for thin minute steaks; they cook in 2 minutes.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p1"], "makes": [], "illustration": {"v": "plate", "c": [["#7A3B2A", "fillet", 0.3], ["#F6F1E4", "wedge", 0.25], ["#E07A2F", "cubes", 0.2], ["#3E7B3A", "leaves", 0.12]]}, "source_id": "b23", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('High-protein grjónagrautur', 'Prótein-grjónagrautur', 'Rice pudding is easy to digest and comforting, and the milk provides calcium and iodine. Adding skyr after cooking roughly doubles the protein, and cinnamon and berries replace the usual sugar.', 'breakfast', array['150 g short-grain rice', '1 L lactose-free whole milk', '400 g skyr', '200 g frozen blueberries', '10 g butter', 'Cinnamon, pinch of salt, ½ vanilla pod']::text[], array['Simmer rice in 200 ml water for 5 minutes. Add the milk, salt and vanilla and cook on low for 35–40 minutes, stirring often.', 'Cool slightly, then stir in the skyr.', 'Serve warm or cold with cinnamon and berries instead of sugar.']::text[], 45, 4, 401, 23, 51, 12, array['meal-prep']::text[], '{"why": "Rice pudding is easy to digest and comforting, and the milk provides calcium and iodine. Adding skyr after cooking roughly doubles the protein, and cinnamon and berries replace the usual sugar.", "highlights": ["Calcium", "Comfort food", "Protein boost"], "tip": "Iceland''s childhood favourite without the sugar. Stirring skyr into rice pudding doubles its protein.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F2EAD6", "c": [["#3D4A7A", "dots", 0.25], ["#A0703A", "crumble", 0.06]]}, "source_id": "b24", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smoked salmon & chive omelette roll', 'Eggjarúlla með reyktum laxi', 'Eggs and smoked salmon together give complete protein, omega-3 fats and vitamin D, a nutrient most Icelanders run short of from October to March. Rolled and sliced, it travels well as a cold breakfast.', 'breakfast', array['3 eggs', '60 g smoked salmon', '40 g skyr', '8 g butter', 'Greens', 'Cucumber', 'Chives, dill, lemon']::text[], array['Whisk eggs with salt and plenty of chopped chives.', 'Cook in butter in a large pan over medium-low heat, tilting until just set and still moist on top.', 'Spread with skyr, lay over the salmon and dill, roll up and cut into thick slices.', 'Serve with greens and cucumber.']::text[], 10, 1, 451, 41, 6, 29, NULL, '{"why": "Eggs and smoked salmon together give complete protein, omega-3 fats and vitamin D, a nutrient most Icelanders run short of from October to March. Rolled and sliced, it travels well as a cold breakfast.", "highlights": ["Omega-3", "Vitamin D", "Portable"], "tip": "Sliced into spirals it travels well: a great cold breakfast or lunch on the go.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F3D36E", "slices", 0.35], ["#EE8C6C", "fillet", 0.15], ["#6E9E3E", "leaves", 0.25]]}, "source_id": "b25", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sardine & egg toast', 'Sardínur og egg á súrdeigsbrauði', 'Sardines are among the richest sources of omega-3 and, because you eat the soft bones, also of calcium. Small fish sit low in the food chain, so they carry very little mercury and are one of the most sustainable proteins there is.', 'breakfast', array['1 thick slice sourdough', '1 tin sardines in olive oil, drained', '1 jammy egg', '30 g skyr', 'Tomato slices', 'Lemon', 'Parsley, chili flakes, black pepper']::text[], array['Toast the bread and spread with skyr.', 'Layer tomato, then sardines, mashing them lightly with a fork.', 'Top with the halved egg, lemon, parsley and chili.']::text[], 10, 1, 457, 39, 34, 17, NULL, '{"why": "Sardines are among the richest sources of omega-3 and, because you eat the soft bones, also of calcium. Small fish sit low in the food chain, so they carry very little mercury and are one of the most sustainable proteins there is.", "highlights": ["Omega-3", "Calcium", "Sustainable"], "tip": "Tinned fish is having a moment, and rightly: sardines are cheap, sustainable and among the richest omega-3 foods there are.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": ["p6"], "makes": [], "illustration": {"v": "board", "c": [["#B98A55", "slices", 0.3], ["#8B9AA3", "fillet", 0.3], ["#F6F1E4", "wedge", 0.15], ["#D6493A", "slices", 0.12]]}, "source_id": "b26", "source_category": "breakfast"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Bulgogi-style beef rice bowl', 'Kóreskur nautakjötsréttur', 'Beef provides heme iron, zinc and B12, and ginger supports digestion. Pickled cucumber, carrots and spinach add crunch, fibre and folate. The flavour comes from tamari and orange instead of sugary sauces.', 'lunch', array['600 g thinly sliced sirloin or beef mince', '3 tbsp tamari', '1 tbsp grated ginger', '1 garlic clove', 'Juice of ½ orange (instead of sugar)', '1 tbsp avocado oil', '280 g white rice (dry)', '1 cucumber, quick-pickled in lime and salt', '2 carrots, julienned', '200 g spinach, wilted', 'Spring onion greens, chili flakes']::text[], array['Mix tamari, ginger, garlic and orange juice. Marinate the beef 15 minutes.', 'Cook the rice. Slice cucumber thinly and toss with lime and salt.', 'Sear the beef in avocado oil over very high heat in batches, 2–3 minutes until caramelised.', 'Box with rice, spinach, carrot and pickled cucumber. Finish with spring onion greens.']::text[], 25, 4, 630, 41, 68, 22, array['meal-prep', 'freezer']::text[], '{"why": "Beef provides heme iron, zinc and B12, and ginger supports digestion. Pickled cucumber, carrots and spinach add crunch, fibre and folate. The flavour comes from tamari and orange instead of sugary sauces.", "highlights": ["Iron & B12", "Ginger", "Street-food flavour"], "tip": "Korean street food made clean: orange juice gives the sweetness instead of sugar, and avocado oil replaces sesame oil.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#6A3A28", "strands", 0.3], ["#F4F1E8", "dots", 0.25], ["#93B957", "slices", 0.15], ["#E58A2E", "strands", 0.12], ["#2F5E35", "leaves", 0.1]]}, "source_id": "l18", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smoked mackerel rice bowl with pickled cucumber', 'Makrílskál', 'Mackerel is one of the oiliest fish in the sea, with even more omega-3 than salmon per gram, plus vitamin D and selenium. Pickled cucumber and mustard cut the richness. A cheap, anti-inflammatory lunch that needs no cooking.', 'lunch', array['90 g smoked mackerel (makríll)', '160 g cooked white rice', '1 boiled egg', 'Cucumber, quick-pickled', 'Raw carrot', '50 g skyr with mustard & dill', 'Lemon']::text[], array['Flake the mackerel over the rice.', 'Add the egg, pickled cucumber and carrot.', 'Dollop on mustard-dill skyr and squeeze over lemon.']::text[], 5, 1, 628, 36, 57, 28, array['meal-prep']::text[], '{"why": "Mackerel is one of the oiliest fish in the sea, with even more omega-3 than salmon per gram, plus vitamin D and selenium. Pickled cucumber and mustard cut the richness. A cheap, anti-inflammatory lunch that needs no cooking.", "highlights": ["Omega-3", "Vitamin D", "No cooking"], "tip": "Smoked mackerel needs no cooking and keeps for over a week sealed. A rich, satisfying lunch for very little money.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["p3"], "makes": [], "illustration": {"v": "bowl", "c": [["#B07A4A", "fillet", 0.3], ["#F4F1E8", "dots", 0.3], ["#93B957", "slices", 0.15], ["#F6F1E4", "wedge", 0.1]]}, "source_id": "l19", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken souvlaki box', 'Kjúklingasouvlaki', 'The yogurt marinade tenderises the chicken and adds tang, while tomato, cucumber, olive oil and feta give a Mediterranean pattern linked to lower inflammation. Tzatziki adds live cultures.', 'lunch', array['800 g boneless chicken thighs, cubed', '100 g Greek yogurt (marinade)', '1 lemon', '1 garlic clove', '1½ tbsp olive oil', '240 g white rice (dry)', 'Tomatoes', 'Cucumber', '80 g feta', '240 g tzatziki', 'Oregano, smoked paprika, salt']::text[], array['Marinate chicken in yogurt, lemon, garlic, oregano, paprika and salt for 30 minutes or overnight.', 'Thread onto skewers or spread on a tray. Grill or bake at 220 °C for 18–20 minutes until charred at the edges.', 'Cook the rice. Chop tomato and cucumber with feta, olive oil and oregano.', 'Box with rice, salad and tzatziki.']::text[], 35, 4, 690, 52, 58, 27, array['meal-prep']::text[], '{"why": "The yogurt marinade tenderises the chicken and adds tang, while tomato, cucumber, olive oil and feta give a Mediterranean pattern linked to lower inflammation. Tzatziki adds live cultures.", "highlights": ["High protein", "Mediterranean", "Gut-friendly"], "tip": "The yogurt marinade tenderises the meat, so it stays juicy for four days of lunches.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": ["p4"], "makes": [], "illustration": {"v": "box", "c": [["#C99A5B", "cubes", 0.3], ["#F4F1E8", "dots", 0.2], ["#D6493A", "cubes", 0.15], ["#93B957", "cubes", 0.12], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "l20", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken & avocado cottage cheese wrap', 'Kjúklingavefja úr kotasælu', 'The wrap is made of kotasæla and egg, so even the bread contributes protein. Avocado adds monounsaturated fat and fibre. A sandwich-style lunch that keeps blood sugar steady through the afternoon.', 'lunch', array['1 cottage cheese flatbread (see breakfast recipe)', '(made with 1 egg)', '100 g cooked chicken', '¼–½ avocado', 'Lettuce', 'Tomato', '30 g skyr with mustard']::text[], array['Spread the flatbread with mustard skyr.', 'Fill with chicken, avocado, lettuce and tomato, roll tightly and wrap in baking paper.']::text[], 5, 1, 503, 53, 13, 27, NULL, '{"why": "The wrap is made of kotasæla and egg, so even the bread contributes protein. Avocado adds monounsaturated fat and fibre. A sandwich-style lunch that keeps blood sugar steady through the afternoon.", "highlights": ["Flour-free", "45 g protein", "Healthy fats"], "tip": "A flour-free wrap with over 45 g protein. Make the flatbreads on Sunday.", "fodmap_note": null, "serving_note": null, "keeps_days": 1, "meal_prep": false, "freezer": false, "uses_prep": ["d6"], "makes": [], "illustration": {"v": "board", "c": [["#E9C77E", "slices", 0.35], ["#C99A5B", "strands", 0.2], ["#8DB255", "slices", 0.15], ["#6E9E3E", "leaves", 0.12]]}, "source_id": "l21", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Egg roll in a bowl', 'Eggjarúlla í skál', 'Shredded cabbage and carrot bulk out the bowl with fibre and vitamin C for very few calories, while beef and egg cover the protein. Ginger aids digestion. All the flavour of a spring roll with nothing fried.', 'lunch', array['600 g organic beef or pork mince', '400 g white cabbage, finely shredded', '2 carrots, grated', '1 tbsp ginger', '1 garlic clove', '3 tbsp tamari', '1 tbsp avocado oil', '4 eggs, fried, to serve', '160 g white rice (dry)', 'Spring onion greens, chili, lime']::text[], array['Brown the mince in avocado oil until crispy.', 'Add ginger and garlic for 30 seconds, then cabbage, carrot and tamari. Stir-fry 5 minutes until just tender.', 'Portion with a little rice and top with a fried egg, spring onion greens and lime.']::text[], 20, 4, 619, 42, 44, 29, array['meal-prep']::text[], '{"why": "Shredded cabbage and carrot bulk out the bowl with fibre and vitamin C for very few calories, while beef and egg cover the protein. Ginger aids digestion. All the flavour of a spring roll with nothing fried.", "highlights": ["Low carb", "Ginger", "Vegetables"], "tip": "All the flavour of a spring roll with none of the deep-frying. A viral low-carb favourite that reheats perfectly.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "skillet", "c": [["#E6E0B8", "strands", 0.35], ["#6A2A1E", "crumble", 0.25], ["#E58A2E", "strands", 0.12], ["#F6F1E4", "wedge", 0.15]]}, "source_id": "l22", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Tuna niçoise box', 'Túnfisksalat niçoise', 'Tuna and eggs make this a high-protein salad, and cooled potatoes provide resistant starch that feeds the gut. Olives and olive oil add healthy fats. A naturally low-FODMAP classic.', 'lunch', array['1 can tuna, drained', '150 g boiled potatoes, cooled', '75 g green beans, blanched', '2 boiled eggs', 'Cherry tomatoes', 'Black olives', '2 tsp extra-virgin olive oil', 'Dijon, lemon']::text[], array['Whisk olive oil, lemon and mustard in the bottom of a box.', 'Add potatoes and beans, then arrange tuna, halved eggs, tomatoes and olives on top.']::text[], 5, 1, 579, 51, 36, 25, array['meal-prep']::text[], '{"why": "Tuna and eggs make this a high-protein salad, and cooled potatoes provide resistant starch that feeds the gut. Olives and olive oil add healthy fats. A naturally low-FODMAP classic.", "highlights": ["Lean protein", "Resistant starch", "Low FODMAP"], "tip": "A French classic that is naturally low FODMAP and needs only a pot of boiled potatoes and eggs.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "box", "c": [["#B8A28A", "chunks", 0.25], ["#E9D9A6", "balls", 0.2], ["#2F6E35", "strands", 0.15], ["#F6F1E4", "wedge", 0.15], ["#D6493A", "balls", 0.1]]}, "source_id": "l23", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Salmon patties with tzatziki', 'Laxabuff', 'Homemade salmon patties deliver omega-3 and vitamin D in a form that kids and fish-sceptics enjoy. Oats replace breadcrumbs, and the patties freeze and reheat well.', 'lunch', array['600 g salmon, skinned', '1 egg', '40 g oats, blended', 'Spring onion greens', 'Zest and juice of ½ lemon', 'Avocado oil for frying', '240 g tzatziki', '200 g white rice (dry)', 'Cucumber', 'Dill, salt, pepper']::text[], array['Pulse half the salmon to a paste and finely chop the rest. Mix with egg, oats, spring onion greens, dill, lemon and salt.', 'Shape into 12 small patties and chill 10 minutes.', 'Fry in avocado oil over medium heat, 3 minutes per side, until just cooked through.', 'Serve with rice, cucumber and tzatziki. Good cold too.']::text[], 30, 4, 662, 41, 51, 30, array['meal-prep', 'freezer']::text[], '{"why": "Homemade salmon patties deliver omega-3 and vitamin D in a form that kids and fish-sceptics enjoy. Oats replace breadcrumbs, and the patties freeze and reheat well.", "highlights": ["Omega-3", "Vitamin D", "Freezer-ready"], "tip": "Chopping half the fish by hand keeps the patties juicy and flaky rather than rubbery.", "fodmap_note": null, "serving_note": "3 patties", "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#D98C64", "balls", 0.35], ["#F4F1E8", "dots", 0.25], ["#93B957", "slices", 0.15], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "l24", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Thai chicken larb with rice', 'Tælenskt kjúklingasalat (larb)', 'Chicken mince gives lean protein, while lime, mint and coriander add flavour and antioxidants without sauces from a jar. Fresh, light and very gentle on the gut.', 'lunch', array['600 g chicken thigh mince (or finely chopped)', '2 tbsp fish sauce (anchovy + salt only)', '2 limes', '180 g white rice (dry), plus 1 tbsp toasted to crush', '2 tsp avocado oil', 'Little gem lettuce cups', 'Cucumber', 'Carrot', 'Mint, coriander, chili, spring onion greens']::text[], array['Toast 1 tbsp raw rice in a dry pan until golden and crush it. This is the classic larb crunch.', 'Cook the chicken in avocado oil, breaking it up, until no longer pink. Take off the heat.', 'Stir in fish sauce, lime juice, chili, herbs and the toasted rice.', 'Serve with rice, lettuce cups, cucumber and carrot.']::text[], 20, 3, 543, 45, 56, 15, array['meal-prep']::text[], '{"why": "Chicken mince gives lean protein, while lime, mint and coriander add flavour and antioxidants without sauces from a jar. Fresh, light and very gentle on the gut.", "highlights": ["Lean protein", "Fresh herbs", "Low FODMAP"], "tip": "Bright, fresh and low FODMAP: Thai flavour comes from lime, fish sauce and herbs, not sauces in jars.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#D7B484", "crumble", 0.35], ["#F4F1E8", "dots", 0.2], ["#6E9E3E", "leaves", 0.25], ["#93B957", "slices", 0.1]]}, "source_id": "l25", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Cobb salad box', 'Cobb-salat', 'Chicken, eggs and parmesan cover protein from three sources, avocado and olive oil provide healthy fats, and tomatoes add lycopene. The variety of colours means a variety of nutrients.', 'lunch', array['120 g cooked chicken', '2 boiled eggs', '¼–½ avocado', 'Tomato', 'Crisp lettuce', '15 g shaved parmesan', '2 tsp olive oil', 'Mustard, lemon']::text[], array['Lay lettuce in a wide box and arrange chicken, eggs, avocado and tomato in rows on top.', 'Shave over parmesan. Shake the olive oil, mustard and lemon in a small jar and dress just before eating.']::text[], 5, 1, 647, 53, 12, 43, array['meal-prep']::text[], '{"why": "Chicken, eggs and parmesan cover protein from three sources, avocado and olive oil provide healthy fats, and tomatoes add lycopene. The variety of colours means a variety of nutrients.", "highlights": ["Complete protein", "Healthy fats", "Colourful"], "tip": "Arranging in rows looks good and keeps the ingredients from going soggy.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["p2", "d6"], "makes": [], "illustration": {"v": "box", "c": [["#C99A5B", "strands", 0.22], ["#F6F1E4", "wedge", 0.2], ["#8DB255", "slices", 0.15], ["#D6493A", "cubes", 0.15], ["#6E9E3E", "leaves", 0.15]]}, "source_id": "l26", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Icelandic shrimp & avocado rice bowl', 'Rækjuskál', 'Cold-water shrimp is very lean protein and rich in iodine and selenium, which support the thyroid. Avocado and rice round it into a balanced, light lunch.', 'lunch', array['150 g cooked Icelandic shrimp (rækjur)', '160 g cooked white rice', '¼–½ avocado', 'Cucumber', 'Carrot', '50 g skyr with lemon & chili', '1 tsp tamari', 'Lime, coriander']::text[], array['Thaw the shrimp in a sieve under cold water if frozen and pat dry.', 'Top the rice with shrimp, avocado, cucumber and carrot.', 'Spoon over chili-lemon skyr and finish with tamari, lime and coriander.']::text[], 5, 1, 492, 42, 60, 10, array['meal-prep']::text[], '{"why": "Cold-water shrimp is very lean protein and rich in iodine and selenium, which support the thyroid. Avocado and rice round it into a balanced, light lunch.", "highlights": ["Lean protein", "Iodine", "Selenium"], "tip": "Cold-water rækjur are sweet, lean and caught around Iceland. Buy them frozen and cooked for an instant lunch.", "fodmap_note": null, "serving_note": null, "keeps_days": 1, "meal_prep": true, "freezer": false, "uses_prep": ["p3"], "makes": [], "illustration": {"v": "bowl", "c": [["#F2A08A", "balls", 0.3], ["#F4F1E8", "dots", 0.25], ["#8DB255", "slices", 0.15], ["#93B957", "slices", 0.12]]}, "source_id": "l27", "source_category": "lunch"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Steak with chimichurri & sweet potato wedges', 'Nautasteik með chimichurri', 'A quality steak is one of the most nutrient-dense foods: heme iron, zinc, B12, creatine and complete protein. Chimichurri brings fresh herbs and olive oil, and sweet potato adds fibre and beta-carotene.', 'dinner', array['2 sirloin steaks (≈180 g each)', '400 g sweet potato wedges', 'Avocado oil', '15 g butter', '1½ tbsp extra-virgin olive oil (chimichurri)', '½ garlic clove', 'Tenderstem broccoli', 'Red wine vinegar or lemon', 'Parsley, oregano, chili flakes, flaky salt']::text[], array['Roast sweet potato wedges in avocado oil at 220 °C for 25–30 minutes.', 'Chimichurri: finely chop a big bunch of parsley with oregano, garlic and chili, and stir in olive oil, vinegar and salt.', 'Salt the steaks well 30 minutes ahead. Sear in a smoking-hot pan with avocado oil, 2–3 minutes per side, adding butter at the end to baste.', 'Rest 5 minutes (aim for 52–54 °C inside for medium-rare) and serve with wedges, broccoli and chimichurri.']::text[], 35, 2, 782, 45, 47, 47, NULL, '{"why": "A quality steak is one of the most nutrient-dense foods: heme iron, zinc, B12, creatine and complete protein. Chimichurri brings fresh herbs and olive oil, and sweet potato adds fibre and beta-carotene.", "highlights": ["Iron & zinc", "Creatine", "Weekend treat"], "tip": "Resting is not optional: it keeps the juices in the steak rather than on the board.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#7A3B2A", "fillet", 0.35], ["#E07A2F", "slices", 0.25], ["#3E7B3A", "crumble", 0.12], ["#2F6E35", "leaves", 0.15]]}, "source_id": "d13", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Crispy-skin arctic char with rice & cucumber salad', 'Bleikja með stökku roði', 'Arctic char is a close cousin of salmon with similar omega-3 fats and a milder taste. Crispy skin adds flavour and extra healthy fat. Cucumber salad and dill skyr keep it light and gut-friendly.', 'dinner', array['2 arctic char fillets, skin on', '2 tsp avocado oil', '15 g butter', '140 g white rice (dry)', 'Cucumber', '100 g skyr with dill', 'Lemon', 'Dill, flaky salt']::text[], array['Cook the rice. Slice cucumber thinly and toss with dill, lemon and salt.', 'Pat the fish skin completely dry and salt it. Lay skin-side down in a hot pan with avocado oil and press gently for 20 seconds so it stays flat.', 'Cook 4–5 minutes until the skin is crisp and the flesh is opaque two-thirds of the way up. Flip, add butter, and give it 30 seconds.', 'Serve skin-up on rice with the cucumber salad and dill skyr.']::text[], 25, 2, 654, 48, 62, 23, NULL, '{"why": "Arctic char is a close cousin of salmon with similar omega-3 fats and a milder taste. Crispy skin adds flavour and extra healthy fat. Cucumber salad and dill skyr keep it light and gut-friendly.", "highlights": ["Omega-3", "Local fish", "Gentle"], "tip": "Bleikja is farmed sustainably in Icelandic spring water. Thin fillets cook almost entirely on the skin side.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#E8946C", "fillet", 0.35], ["#F4F1E8", "dots", 0.25], ["#93B957", "slices", 0.2]]}, "source_id": "d14", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken shawarma tray with rice', 'Kjúklingashawarma', 'Cumin, turmeric and coriander add antioxidants and big flavour with no sauce needed. Thighs stay juicy for days, and with rice and tzatziki it makes balanced lunch boxes.', 'dinner', array['900 g boneless chicken thighs', '100 g Greek yogurt (marinade)', '1 lemon', '1 garlic clove', '2 tbsp avocado oil', '2 peppers', '2 carrots', '240 g white rice (dry)', '240 g tzatziki', 'Tomato & parsley salad', 'Cumin, coriander, paprika, cinnamon, turmeric, salt']::text[], array['Marinate chicken with yogurt, lemon, garlic, spices and half the oil for at least 30 minutes.', 'Spread on a tray with peppers and carrots tossed in the remaining oil. Roast at 220 °C for 25 minutes, then grill 3 minutes for charred edges.', 'Slice the chicken and serve with rice, tzatziki and tomato salad.']::text[], 45, 4, 701, 55, 62, 25, array['meal-prep']::text[], '{"why": "Cumin, turmeric and coriander add antioxidants and big flavour with no sauce needed. Thighs stay juicy for days, and with rice and tzatziki it makes balanced lunch boxes.", "highlights": ["High protein", "Spices", "Meal prep"], "tip": "The spice mix does the work of a shop shawarma sauce with none of the sugar or seed oil.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["Shawarma lunch boxes"], "illustration": {"v": "tray", "c": [["#C68A4A", "strands", 0.35], ["#F4F1E8", "dots", 0.2], ["#C8402E", "slices", 0.12], ["#E58A2E", "cubes", 0.12], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "d15", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smash burger bowl', 'Hamborgaraskál', 'Proof that healthy food can be fun. Organic beef provides iron, zinc and B12, the skyr burger sauce adds protein instead of sugar, and sweet potato fries are roasted rather than deep-fried.', 'dinner', array['600 g organic beef mince', '4 slices cheese', 'Crisp lettuce, shredded', 'Tomatoes', 'Dill pickles (no sugar)', '600 g sweet potato fries', 'Avocado oil', '150 g skyr', 'Mustard', '1 tbsp tomato paste', 'Smoked paprika, salt, pepper']::text[], array['Roast sweet potato fries in avocado oil at 220 °C for 25 minutes.', 'Burger sauce: mix skyr, mustard, tomato paste, chopped pickles, paprika and salt.', 'Roll the beef into 8 balls. Smash each flat in a smoking-hot pan, season, and cook 2 minutes until crusty. Flip, add cheese, and cook 1 more minute.', 'Build bowls with lettuce, tomato, pickles, patties, fries and burger sauce.']::text[], 25, 4, 608, 42, 37, 32, array['meal-prep']::text[], '{"why": "Proof that healthy food can be fun. Organic beef provides iron, zinc and B12, the skyr burger sauce adds protein instead of sugar, and sweet potato fries are roasted rather than deep-fried.", "highlights": ["Iron & B12", "Fun food", "No bun"], "tip": "All the joy of a burger with a skyr ''special sauce'' and no bun. A huge hit on Instagram and TikTok.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#5E2E20", "balls", 0.3], ["#E07A2F", "strands", 0.2], ["#6E9E3E", "leaves", 0.2], ["#D6493A", "slices", 0.1], ["#F2D06B", "smooth", 0.08]]}, "source_id": "d16", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Lamb kofta with rice & tzatziki', 'Lambakofta', 'Icelandic lamb is grass-fed and rich in heme iron, zinc and B12. Warm spices like cumin and cinnamon add flavour and antioxidants, and the fresh salad and tzatziki balance the richness.', 'dinner', array['600 g lamb mince', '1 egg', 'Spring onion greens', '240 g white rice (dry)', '240 g tzatziki with mint', 'Cucumber', 'Tomato', 'Lemon', 'Cumin, coriander, cinnamon, parsley, mint, salt']::text[], array['Mix lamb, egg, spring onion greens, spices and herbs. Shape into 12 fingers around skewers or by hand.', 'Grill or roast at 220 °C for 12–14 minutes, turning once.', 'Serve with rice, a chopped salad of cucumber, tomato, parsley and lemon, and minted tzatziki.']::text[], 30, 4, 734, 36, 55, 40, array['meal-prep', 'freezer']::text[], '{"why": "Icelandic lamb is grass-fed and rich in heme iron, zinc and B12. Warm spices like cumin and cinnamon add flavour and antioxidants, and the fresh salad and tzatziki balance the richness.", "highlights": ["Iron & zinc", "Grass-fed", "Freezer-ready"], "tip": "Icelandic lamb mince is rich, so it needs no added fat. The spices make it taste like a holiday.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#7A3E2A", "fillet", 0.35], ["#F4F1E8", "dots", 0.25], ["#93B957", "cubes", 0.15], ["#F4F3EE", "smooth", 0.1]]}, "source_id": "d17", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Ginger-tamari salmon with rice & greens', 'Lax með engifer og tamari', 'Salmon''s omega-3s support heart, brain and joint health, and ginger adds digestive benefits. Gentle baking keeps the fish moist, and the greens add folate, vitamin K and sulforaphane.', 'dinner', array['600 g salmon', '2 tbsp tamari', '1 tbsp ginger', 'Juice of ½ orange', '280 g white rice (dry)', 'Broccoli florets', 'Spinach', '2 tsp avocado oil', 'Spring onion greens, chili, lime']::text[], array['Mix tamari, ginger and orange juice. Pour over the salmon and leave 10 minutes.', 'Bake at 140 °C for 12–15 minutes until 48–50 °C in the centre, basting once with the marinade.', 'Stir-fry broccoli and spinach in avocado oil for 3 minutes.', 'Serve with rice, spring onion greens, chili and lime.']::text[], 25, 4, 636, 40, 65, 23, array['meal-prep']::text[], '{"why": "Salmon''s omega-3s support heart, brain and joint health, and ginger adds digestive benefits. Gentle baking keeps the fish moist, and the greens add folate, vitamin K and sulforaphane.", "highlights": ["Omega-3", "Vitamin D", "Ginger"], "tip": "A clean ''teriyaki'': orange juice brings the gloss and sweetness instead of sugar.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["2 dinners + 2 lunch bowls"], "illustration": {"v": "plate", "c": [["#D9774E", "fillet", 0.3], ["#F4F1E8", "dots", 0.25], ["#2F6E35", "leaves", 0.3]]}, "source_id": "d18", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Shepherd''s pie with sweet potato top', 'Lambabaka með sætkartöflum', 'Lamb mince provides iron and B12, and a sweet potato topping replaces white mash with one rich in beta-carotene and fibre. Parmesan gives a crisp, protein-rich crust.', 'dinner', array['800 g lamb mince', '3 carrots, diced', 'Green parts of 2 leeks', '2 tbsp tomato paste', '200 g canned tomatoes', '900 g sweet potato', '30 g butter', '40 g parmesan', 'Thyme, rosemary, salt, pepper, 200 ml water']::text[], array['Brown the lamb well, pour off excess fat, then add carrot and leek greens for 5 minutes.', 'Stir in tomato paste, tomatoes, herbs and water. Simmer 20 minutes until thick.', 'Boil sweet potato 15 minutes, drain and mash with butter and salt.', 'Spread the lamb in a dish, top with mash and parmesan, and bake at 200 °C for 25 minutes.']::text[], 70, 6, 614, 28, 41, 37, array['meal-prep', 'freezer']::text[], '{"why": "Lamb mince provides iron and B12, and a sweet potato topping replaces white mash with one rich in beta-carotene and fibre. Parmesan gives a crisp, protein-rich crust.", "highlights": ["Iron", "Vitamin A", "Batch"], "tip": "Six portions of pure comfort food. Freeze in single portions for busy weeks.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "tray", "c": [["#E8913A", "smooth", 0.45], ["#F1E7C9", "crumble", 0.2], ["#6A2A1E", "crumble", 0.15]]}, "source_id": "d19", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Lemon-herb roast chicken with rice', 'Heilsteiktur kjúklingur', 'Roasting a whole bird is the most economical way to buy chicken, and the bones become a collagen-rich broth for soups. Fennel and carrots roast in the juices and add fibre and vitamins.', 'dinner', array['1 whole chicken (≈1.6 kg, ≈1 kg edible meat)', '30 g butter', '1 lemon', '1 garlic clove', '4 carrots', '1 small fennel bulb', '300 g white rice (dry)', '1 tbsp avocado oil', 'Thyme, rosemary, flaky salt']::text[], array['Dry the chicken well and salt it all over, ideally the night before, uncovered in the fridge.', 'Rub with butter mixed with lemon zest, garlic and thyme. Put the lemon halves inside.', 'Roast at 200 °C on top of carrots and fennel tossed in avocado oil for about 70 minutes, until the thigh reaches 75 °C.', 'Rest 15 minutes. Serve with rice and the pan juices. Keep the carcass for broth.']::text[], 90, 5, 764, 43, 59, 38, array['meal-prep']::text[], '{"why": "Roasting a whole bird is the most economical way to buy chicken, and the bones become a collagen-rich broth for soups. Fennel and carrots roast in the juices and add fibre and vitamins.", "highlights": ["Complete protein", "Collagen broth", "Whole bird"], "tip": "Dry-salting overnight gives crackling-crisp skin. The bones make a free pot of broth for soups.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": ["Chicken for lunches", "Bones for broth"], "illustration": {"v": "tray", "c": [["#C98E4A", "fillet", 0.4], ["#E39A3B", "cubes", 0.2], ["#D8E0B4", "slices", 0.12], ["#F4F1E8", "dots", 0.1]]}, "source_id": "d20", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Crispy fish tacos with lime slaw', 'Fisktakkó', 'Cod or haddock gives lean, iodine-rich protein, coated in oats instead of breadcrumbs. Corn tortillas are naturally wheat-free and low FODMAP, and the cabbage slaw adds crunch and vitamin C.', 'dinner', array['450 g cod or haddock', '150 g masa harina (for 9 corn tortillas)', '30 g oats, blended (coating)', '1 egg', 'Avocado oil for frying', 'Red or white cabbage, finely shredded', '2 limes', '150 g guacamole', '120 g skyr with chili & lime', 'Coriander, smoked paprika, salt']::text[], array['Tortillas: mix masa harina with about 220 ml warm water and a pinch of salt. Press or roll 9 thin rounds and cook in a dry pan, 45 seconds per side.', 'Toss cabbage with lime and salt.', 'Cut the fish into strips, dip in beaten egg and then in oat flour mixed with paprika and salt. Fry in avocado oil 2 minutes per side.', 'Fill tortillas with slaw, fish, guacamole, chili-lime skyr and coriander.']::text[], 35, 3, 580, 42, 56, 22, NULL, '{"why": "Cod or haddock gives lean, iodine-rich protein, coated in oats instead of breadcrumbs. Corn tortillas are naturally wheat-free and low FODMAP, and the cabbage slaw adds crunch and vitamin C.", "highlights": ["Lean protein", "Iodine", "Wheat-free"], "tip": "Corn tortillas are naturally wheat-free and low FODMAP. Masa harina is just corn, lime and water.", "fodmap_note": null, "serving_note": "3 tacos", "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E8D09A", "slices", 0.3], ["#E2B26A", "fillet", 0.25], ["#A04A7A", "strands", 0.15], ["#8DB255", "smooth", 0.1]]}, "source_id": "d21", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Pork tenderloin with mustard skyr sauce', 'Svínalund með sinnepssósu', 'Pork tenderloin is as lean as chicken breast and one of the best sources of thiamine (B1), which the body uses to turn food into energy. Mustard skyr replaces a cream sauce.', 'dinner', array['700 g pork tenderloin', '1 tbsp avocado oil', '20 g butter', '600 g sweet potato', '4 carrots', 'Green beans', '200 g skyr', '2 tbsp wholegrain mustard', 'Thyme, rosemary, salt, pepper']::text[], array['Roast sweet potato and carrot chunks at 210 °C for 30 minutes.', 'Brown the pork on all sides in avocado oil, add butter and thyme, then finish in the oven for 12–15 minutes until 62 °C in the centre. Rest 10 minutes.', 'Stir mustard into skyr with a spoon of the pan juices.', 'Slice the pork and serve with the vegetables, green beans and sauce.']::text[], 35, 4, 501, 47, 46, 15, array['meal-prep']::text[], '{"why": "Pork tenderloin is as lean as chicken breast and one of the best sources of thiamine (B1), which the body uses to turn food into energy. Mustard skyr replaces a cream sauce.", "highlights": ["Lean protein", "B vitamins", "Quick roast"], "tip": "Tenderloin is the leanest cut of pork. Pull it at 62 °C and it stays pink and juicy, which is perfectly safe for whole pork muscle.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#D9A08A", "slices", 0.35], ["#E07A2F", "cubes", 0.2], ["#2F6E35", "strands", 0.15], ["#E8D9A0", "smooth", 0.1]]}, "source_id": "d22", "source_category": "dinner"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr cheesecake cups', 'Skyrkökubollar', 'Skyr and Greek yogurt give a creamy, cheesecake-like texture with real protein and live cultures. The base is oats and walnuts, and berries sweeten without added sugar.', 'snack', array['300 g skyr', '150 g Greek yogurt', '40 g oats', '30 g walnuts', '15 g butter, melted', '200 g frozen raspberries or blueberries', 'Vanilla, lemon zest, pinch of salt, cinnamon']::text[], array['Blitz oats, walnuts, butter, cinnamon and salt to a crumb. Press into the bottom of 4 small jars.', 'Whisk skyr, Greek yogurt, vanilla and lemon zest and spoon on top.', 'Warm the berries until they collapse into a sauce, cool, and spoon over. Chill.']::text[], 15, 4, 234, 14, 18, 12, array['meal-prep']::text[], '{"why": "Skyr and Greek yogurt give a creamy, cheesecake-like texture with real protein and live cultures. The base is oats and walnuts, and berries sweeten without added sugar.", "highlights": ["Protein dessert", "Live cultures", "No sugar"], "tip": "The cheesecake-cup trend without sugar or cream cheese. Tastes like dessert, eats like a protein snack.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "jar", "base": "#F2EEE4", "c": [["#B0304A", "smooth", 0.25], ["#C9A878", "crumble", 0.25]]}, "source_id": "s4", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Parmesan crisps with smoked salmon', 'Parmesanflögur með laxi', 'Parmesan crisps give the crunch of crisps with mostly protein and fat and almost no carbs. Topped with salmon, they add omega-3s too.', 'snack', array['60 g parmesan, finely grated', '80 g smoked salmon', '40 g skyr', 'Cucumber slices', 'Dill, black pepper, lemon']::text[], array['Heat the oven to 200 °C. Make 12 small mounds of parmesan on baking paper and flatten slightly.', 'Bake 5–6 minutes until golden and lacy. Cool on the tray to crisp.', 'Top each crisp with a dot of skyr, a curl of salmon and dill. Serve with cucumber.']::text[], 15, 2, 202, 22, 4, 11, NULL, '{"why": "Parmesan crisps give the crunch of crisps with mostly protein and fat and almost no carbs. Topped with salmon, they add omega-3s too.", "highlights": ["Crunchy", "Low carb", "Omega-3"], "tip": "Parmesan crisps keep a week in an airtight tin: a crunchy, salty snack that is almost pure protein and fat.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E9C46A", "slices", 0.4], ["#EE8C6C", "fillet", 0.2], ["#93B957", "slices", 0.2]]}, "source_id": "s6", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Frozen yogurt bark', 'Frosið jógúrtnammi', 'A frozen treat made of strained dairy, berries and seeds, so it brings protein, live cultures and polyphenols instead of sugar. A small amount of 85% chocolate adds flavour and cocoa flavanols.', 'snack', array['300 g Greek yogurt', '300 g skyr', '200 g blueberries and raspberries', '30 g pumpkin seeds', '20 g 85% dark chocolate, chopped', 'Vanilla']::text[], array['Mix yogurt, skyr and vanilla and spread 1 cm thick on a baking-paper-lined tray.', 'Scatter over berries, pumpkin seeds and chocolate.', 'Freeze 3 hours, break into shards and keep in a box in the freezer.']::text[], 10, 6, 160, 11, 10, 9, array['meal-prep', 'freezer']::text[], '{"why": "A frozen treat made of strained dairy, berries and seeds, so it brings protein, live cultures and polyphenols instead of sugar. A small amount of 85% chocolate adds flavour and cocoa flavanols.", "highlights": ["Protein treat", "Polyphenols", "Freezer"], "tip": "A viral treat that is really just strained dairy and berries. Take a piece out 5 minutes before eating.", "fodmap_note": null, "serving_note": null, "keeps_days": 30, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "tray", "c": [["#F4F1EA", "smooth", 0.3], ["#3D4A7A", "dots", 0.2], ["#B0304A", "dots", 0.1], ["#5B6B4A", "crumble", 0.08], ["#3A2620", "crumble", 0.06]]}, "source_id": "s7", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr devilled eggs', 'Fyllt egg með skyri', 'Eggs are cheap, complete protein with choline and vitamin D. Skyr replaces mayo for a lighter, higher-protein filling.', 'snack', array['4 hard-boiled eggs', '60 g skyr', '2 tsp Dijon', 'Smoked paprika, chives, salt, pepper']::text[], array['Halve the eggs and mash the yolks with skyr, mustard, salt and pepper until smooth.', 'Pipe or spoon back into the whites. Dust with paprika and chives.']::text[], 15, 2, 194, 19, 2, 12, array['meal-prep']::text[], '{"why": "Eggs are cheap, complete protein with choline and vitamin D. Skyr replaces mayo for a lighter, higher-protein filling.", "highlights": ["Choline", "Low carb", "Party-ready"], "tip": "Skyr replaces mayo, which makes these lighter and higher in protein than the classic.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["p2"], "makes": [], "illustration": {"v": "plate", "c": [["#F6F1E4", "wedge", 0.6], ["#C8402E", "crumble", 0.05]]}, "source_id": "s8", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Smoked salmon cucumber rolls', 'Gúrkurúllur með laxi', 'Salmon and kotasæla provide protein and omega-3, while cucumber adds water and crunch. A light snack that won''t spoil your appetite.', 'snack', array['80 g smoked salmon', '60 g kotasæla', '½ cucumber, sliced lengthways', 'Dill, lemon, black pepper']::text[], array['Slice the cucumber into long ribbons with a peeler.', 'Spread with kotasæla, add salmon and dill, and roll up. Secure with a toothpick.']::text[], 5, 1, 209, 25, 7, 9, NULL, '{"why": "Salmon and kotasæla provide protein and omega-3, while cucumber adds water and crunch. A light snack that won''t spoil your appetite.", "highlights": ["Omega-3", "Low carb", "Fresh"], "tip": "Fresh, crunchy and almost carb-free. Good as a pre-dinner bite instead of bread.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#93B957", "slices", 0.4], ["#EE8C6C", "fillet", 0.25]]}, "source_id": "s9", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Homemade beef jerky', 'Heimagert nautakjötssnakk', 'Drying lean beef concentrates its protein, iron and zinc into a shelf-stable snack. Unlike shop jerky, this has no sugar or preservatives.', 'snack', array['800 g lean beef (silverside or topside), trimmed', '4 tbsp tamari', 'Smoked paprika, black pepper, garlic powder (a pinch), chili']::text[], array['Freeze the beef for 1 hour, then slice across the grain into 4 mm strips.', 'Marinate overnight with tamari and spices.', 'Pat dry and lay on racks. Dry in the oven at 70 °C with the door slightly open for 4–5 hours, until leathery but still bendable.', 'Cool and store in an airtight jar. The 800 g of raw beef makes about 320 g of jerky.']::text[], 300, 8, 134, 23, 0, 5, array['meal-prep']::text[], '{"why": "Drying lean beef concentrates its protein, iron and zinc into a shelf-stable snack. Unlike shop jerky, this has no sugar or preservatives.", "highlights": ["20 g+ protein per bag", "Portable", "No sugar"], "tip": "Shop jerky is usually full of sugar and preservatives. Homemade is pure beef: over 20 g protein per 40 g bag.", "fodmap_note": null, "serving_note": "40 g", "keeps_days": 14, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#5E2A1E", "strands", 0.6]]}, "source_id": "s10", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Steamed edamame with sea salt', 'Edamame-baunir', 'Edamame are young soybeans with complete plant protein, fibre and folate, and they are one of the few legumes that are low FODMAP in a normal portion.', 'snack', array['150 g frozen edamame in pods (≈90 g beans)', 'Flaky sea salt, chili, lime']::text[], array['Boil or steam the edamame for 4 minutes.', 'Toss with flaky salt, chili and a squeeze of lime. Pop the beans out of the pods as you eat.']::text[], 5, 1, 109, 11, 8, 4, NULL, '{"why": "Edamame are young soybeans with complete plant protein, fibre and folate, and they are one of the few legumes that are low FODMAP in a normal portion.", "highlights": ["Plant protein", "Fibre", "Folate"], "tip": "One of the few legumes that is low FODMAP in a normal portion. Popping them from the pods slows you down.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#7FB14A", "fillet", 0.6]]}, "source_id": "s11", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Tuna-stuffed cucumber boats', 'Gúrkubátar með túnfiski', 'Tuna is lean, cheap and very high in protein. The cucumber replaces bread, so the snack is filling and very light.', 'snack', array['1 can tuna, drained', '40 g skyr', '1 small cucumber', 'Mustard, lemon', 'Chives, paprika']::text[], array['Halve the cucumber lengthways and scoop out the seeds.', 'Mix tuna with skyr, mustard, lemon and chives and fill the halves. Dust with paprika.']::text[], 5, 1, 198, 37, 9, 2, NULL, '{"why": "Tuna is lean, cheap and very high in protein. The cucumber replaces bread, so the snack is filling and very light.", "highlights": ["30 g+ protein", "No cooking", "Low carb"], "tip": "More than 30 g protein in a snack that takes 5 minutes and no cooking.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#93B957", "fillet", 0.35], ["#D8D1BF", "crumble", 0.25]]}, "source_id": "s12", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Savoury cottage cheese bowl', 'Kotasæla með tómötum', 'Kotasæla is rich in casein, a slowly digested protein, which makes it ideal between meals or before bed. Tomatoes and olive oil add lycopene and healthy fats.', 'snack', array['200 g kotasæla', 'Cherry tomatoes', 'Cucumber', '1 tsp extra-virgin olive oil', '1 tbsp pumpkin seeds', 'Flaky salt, black pepper, chili flakes, basil']::text[], array['Spoon kotasæla into a bowl, top with halved tomatoes and cucumber.', 'Drizzle with olive oil and finish with pumpkin seeds, salt, pepper, chili and basil.']::text[], 3, 1, 326, 28, 14, 18, NULL, '{"why": "Kotasæla is rich in casein, a slowly digested protein, which makes it ideal between meals or before bed. Tomatoes and olive oil add lycopene and healthy fats.", "highlights": ["Casein", "Lycopene", "3 minutes"], "tip": "Cottage cheese is the protein star of the moment. Savoury is the way to eat it: think burrata on a budget.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F5F2E8", "c": [["#D6493A", "balls", 0.3], ["#93B957", "cubes", 0.15], ["#5B6B4A", "crumble", 0.06]]}, "source_id": "s13", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Icelandic shrimp cocktail', 'Rækjukokteill', 'Icelandic shrimp is lean, iodine-rich protein. Skyr replaces the mayonnaise and ketchup of the classic sauce, cutting the sugar and seed oil.', 'snack', array['120 g cooked rækjur', '60 g skyr', '2 tsp tomato paste', 'Lemon', 'Crisp lettuce', 'Cucumber', 'Paprika, a little horseradish or chili, dill']::text[], array['Mix skyr, tomato paste, lemon, paprika and horseradish into a pink sauce.', 'Layer lettuce and cucumber in a glass, add shrimp and spoon over the sauce. Finish with dill.']::text[], 5, 1, 174, 32, 9, 2, NULL, '{"why": "Icelandic shrimp is lean, iodine-rich protein. Skyr replaces the mayonnaise and ketchup of the classic sauce, cutting the sugar and seed oil.", "highlights": ["Lean protein", "Iodine", "Retro classic"], "tip": "The retro classic, minus the mayonnaise and ketchup.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#F2A08A", "c": []}, "source_id": "s14", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Nut, seed & dark chocolate mix', 'Hnetu- og fræblanda', 'Nuts and seeds provide healthy fats, magnesium, vitamin E and fibre, and walnuts and pumpkin seeds add plant omega-3 and zinc. Portioning into 30 g bags gives you the benefits without overeating.', 'snack', array['80 g almonds', '60 g walnuts', '80 g pumpkin seeds', '20 g 85% dark chocolate, chopped', 'Flaky salt, cinnamon']::text[], array['Toast almonds and pumpkin seeds in a dry pan for 4 minutes. Cool.', 'Mix with walnuts, chocolate, a pinch of salt and cinnamon. Portion into 8 small bags of 30 g.']::text[], 5, 8, 178, 6, 5, 16, array['meal-prep']::text[], '{"why": "Nuts and seeds provide healthy fats, magnesium, vitamin E and fibre, and walnuts and pumpkin seeds add plant omega-3 and zinc. Portioning into 30 g bags gives you the benefits without overeating.", "highlights": ["Healthy fats", "Magnesium", "Pre-portioned"], "tip": "Pre-portioning is the trick: nuts are healthy but easy to overeat straight from the bag.", "fodmap_note": null, "serving_note": "30 g", "keeps_days": 60, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#B07A4A", "chunks", 0.3], ["#5B6B4A", "crumble", 0.25], ["#8A6A45", "chunks", 0.2], ["#3A2620", "crumble", 0.08]]}, "source_id": "s15", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Viral cottage cheese wrap', 'Kotasæluvefja', 'The whole wrap is made of kotasæla and egg, so instead of empty starch it delivers about 35 g of complete protein, mostly slow-digesting casein. It has no emulsifiers, preservatives or seed oils, and it is naturally wheat-free.', 'lunch', array['450 g kotasæla (2 tubs), drained in a sieve for 10 minutes', '2 eggs (or 120 g egg whites for a leaner wrap)', 'A few drops of avocado oil for the paper', '1 tsp dried oregano or Italian herbs, ½ tsp salt, pinch of garlic powder']::text[], array['Heat the oven to 180 °C. Line two baking trays (about 23 × 33 cm) with baking paper and rub with a few drops of avocado oil.', 'Blend kotasæla, eggs, herbs and salt until completely smooth. Lumps make the wrap tear.', 'Spread thinly and evenly over the two trays, about 3–4 mm. A thick centre stays soggy while the edges burn.', 'Bake 30–35 minutes until golden in spots and set all over. Turn the tray halfway if your oven is uneven.', 'Leave to cool on the tray for 5–10 minutes, then peel off the paper slowly. Stack between baking paper in the fridge.']::text[], 40, 2, 320, 35, 8, 16, array['meal-prep', 'wrap']::text[], '{"why": "The whole wrap is made of kotasæla and egg, so instead of empty starch it delivers about 35 g of complete protein, mostly slow-digesting casein. It has no emulsifiers, preservatives or seed oils, and it is naturally wheat-free.", "highlights": ["35 g protein per wrap", "No flour", "Freezer-friendly"], "tip": "The most tested tips from the community: drain the kotasæla, blend until silky, spread thin, and let it cool before peeling. Skip spray oils, which contain propellants and lecithin; a few drops of avocado oil rubbed in works better.", "fodmap_note": null, "serving_note": "1 wrap", "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E6BE6E", "slices", 0.55], ["#6E9E3E", "leaves", 0.08]]}, "source_id": "w1", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('4-minute egg white wraps', 'Eggjahvítuvefjur', 'Egg white is the purest protein in the kitchen, with almost no fat or carbohydrate. A spoon of coconut or oat flour adds fibre and makes it bendy. Ideal when you want a light wrap and plenty of filling.', 'lunch', array['4 egg whites (≈130 g)', '1 tbsp coconut flour (or 2 tbsp fine oat flour)', 'A little butter for the pan', 'Pinch of salt, optional herbs']::text[], array['Whisk egg whites, coconut flour and salt just until smooth. Don''t whip them to foam.', 'Rub a 16–20 cm non-stick pan with butter and heat over medium-low.', 'Pour in half the mixture and tilt to cover the base. Cook 1½–2 minutes until set underneath, flip and cook 30 seconds more.', 'Repeat. Fill while warm, or cool and stack.']::text[], 5, 1, 128, 16, 6, 5, array['meal-prep', 'wrap']::text[], '{"why": "Egg white is the purest protein in the kitchen, with almost no fat or carbohydrate. A spoon of coconut or oat flour adds fibre and makes it bendy. Ideal when you want a light wrap and plenty of filling.", "highlights": ["Lean protein", "Almost no carbs", "4 minutes"], "tip": "Use a small pan: a large one makes the wraps too thin and fragile. Without the flour they turn into a fried egg; the spoon of coconut or oat flour is what makes them bendy.", "fodmap_note": null, "serving_note": "2 wraps", "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F6F0DC", "fillet", 0.45], ["#6E9E3E", "leaves", 0.15]]}, "source_id": "w2", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Parmesan egg crepe wrap', 'Eggjakrepa með parmesan', 'Whole eggs bring choline, vitamin D and B12, and parmesan adds protein and flavour while being almost lactose-free. A wrap that is itself a full serving of protein.', 'lunch', array['2 eggs', '15 g parmesan, finely grated', 'A little butter', 'Pepper, chives']::text[], array['Whisk eggs well with the parmesan and pepper.', 'Melt butter in a 24 cm non-stick pan over medium-low heat, pour in the eggs and swirl to a thin round.', 'Cover with a lid for 1–2 minutes until the top is just set. No flipping needed.', 'Slide onto a board, fill, and roll while warm.']::text[], 5, 1, 259, 21, 1, 19, array['wrap']::text[], '{"why": "Whole eggs bring choline, vitamin D and B12, and parmesan adds protein and flavour while being almost lactose-free. A wrap that is itself a full serving of protein.", "highlights": ["Choline", "Low carb", "Gluten-free"], "tip": "The fastest wrap there is. Parmesan makes it slightly crisp at the edges and more pliable. Great with smoked salmon or leftover chicken.", "fodmap_note": null, "serving_note": "1 wrap", "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "plate", "c": [["#F2D06B", "fillet", 0.45], ["#F1E7C9", "crumble", 0.1]]}, "source_id": "w3", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Soft butter flour tortillas', 'Mjúkar hveiti- eða speltvefjur', 'When you want a classic soft tortilla, making it yourself removes the emulsifiers, preservatives and rapeseed oil in shop wraps. Butter gives flavour and softness. Spelt is often easier on the stomach than modern wheat.', 'lunch', array['250 g spelt or wheat flour', '40 g butter, soft', '1 tsp salt, ½ tsp baking powder, 150 ml warm water']::text[], array['Mix flour, salt and baking powder, and rub in the butter with your fingertips.', 'Add the warm water and knead 2 minutes into a soft, smooth dough. Rest 15 minutes under a cloth.', 'Divide into 8 balls and roll each very thin, about 20 cm across.', 'Cook in a dry, hot pan for 30–40 seconds per side until puffed with brown spots. Stack under a tea towel to keep soft.']::text[], 30, 8, 141, 5, 22, 5, array['meal-prep', 'freezer', 'wrap']::text[], '{"why": "When you want a classic soft tortilla, making it yourself removes the emulsifiers, preservatives and rapeseed oil in shop wraps. Butter gives flavour and softness. Spelt is often easier on the stomach than modern wheat.", "highlights": ["4 ingredients", "No additives", "Classic texture"], "tip": "Four ingredients against the twenty or so on a supermarket pack. Freeze with baking paper between them and reheat 10 seconds in a pan.", "fodmap_note": null, "serving_note": "1 tortilla", "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#EAD5A8", "slices", 0.55], ["#B98A55", "crumble", 0.06]]}, "source_id": "w4", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Corn tortillas', 'Maístortillur', 'Masa harina is corn cooked in limewater, a traditional process that unlocks niacin and adds calcium. Corn tortillas are low FODMAP and gluten-free, the safest choice for a sensitive gut.', 'lunch', array['150 g masa harina', 'Pinch of salt, about 220 ml warm water']::text[], array['Mix masa harina, salt and warm water into a soft dough that feels like play-dough. Add water a spoon at a time if it cracks.', 'Rest 10 minutes, then roll into 9 balls.', 'Press between two pieces of baking paper with a heavy pan or tortilla press to about 2 mm.', 'Cook in a dry, hot pan for 45 seconds per side, until spotted. Keep warm in a tea towel.']::text[], 25, 9, 61, 2, 13, 1, array['meal-prep', 'freezer', 'wrap']::text[], '{"why": "Masa harina is corn cooked in limewater, a traditional process that unlocks niacin and adds calcium. Corn tortillas are low FODMAP and gluten-free, the safest choice for a sensitive gut.", "highlights": ["Low FODMAP", "Wheat-free", "Whole grain corn"], "tip": "Naturally wheat-free and low FODMAP, which makes these the gentlest wrap for sensitive stomachs. Use them for tacos and small wraps.", "fodmap_note": null, "serving_note": "1 tortilla", "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E3C46E", "slices", 0.55]]}, "source_id": "w5", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Two-ingredient skyr flatbreads', 'Skyrflatbrauð', 'Swapping water for skyr in the dough roughly doubles the protein of an ordinary flatbread and gives it a soft, naan-like texture. No yeast, no rising time and no additives.', 'lunch', array['180 g skyr or Greek yogurt', '180 g spelt flour', '1½ tsp baking powder, ½ tsp salt']::text[], array['Mix everything into a soft dough. Knead 1 minute with floured hands.', 'Divide into 4 and roll each into a thin round.', 'Cook in a dry, hot pan for 1½–2 minutes per side until puffed and spotted.']::text[], 15, 4, 180, 12, 33, 1, array['meal-prep', 'freezer', 'wrap']::text[], '{"why": "Swapping water for skyr in the dough roughly doubles the protein of an ordinary flatbread and gives it a soft, naan-like texture. No yeast, no rising time and no additives.", "highlights": ["Double protein", "No yeast", "15 minutes"], "tip": "The viral ''yogurt dough'' made Icelandic with skyr. Soft like naan, with about twice the protein of a shop wrap.", "fodmap_note": null, "serving_note": "1 flatbread", "keeps_days": 3, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#E9CF9A", "slices", 0.5], ["#B98A55", "crumble", 0.08]]}, "source_id": "w6", "source_category": "wrap"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chocolate cottage cheese mousse', 'Súkkulaðimús úr kotasælu', 'Blending kotasæla turns it into a silky mousse with about 31 g of slow-digesting protein. Cocoa is rich in flavanols linked to better blood flow and mood, plus magnesium and iron. With just a teaspoon of maple syrup it satisfies a sweet tooth without a sugar crash.', 'snack', array['225 g kotasæla (1 tub), drained', '2 tbsp unsweetened cocoa or raw cacao', '1 tsp maple syrup (or a few drops of pure stevia)', '1 tsp chia seeds', 'Raspberries to top', '¼ tsp vanilla, tiny pinch of salt']::text[], array['Blend kotasæla, cocoa, maple syrup, vanilla, salt and chia for 45–60 seconds, scraping down, until completely smooth and glossy. Any graininess means keep blending.', 'Spoon into a glass and chill at least 30 minutes to set to a mousse.', 'Top with raspberries and a few shavings of 85% chocolate if you like.']::text[], 5, 1, 316, 31, 27, 13, array['meal-prep']::text[], '{"why": "Blending kotasæla turns it into a silky mousse with about 31 g of slow-digesting protein. Cocoa is rich in flavanols linked to better blood flow and mood, plus magnesium and iron. With just a teaspoon of maple syrup it satisfies a sweet tooth without a sugar crash.", "highlights": ["31 g protein", "Cocoa flavanols", "Low sugar"], "tip": "This is the Instagram favourite, made with a fraction of the sugar. The viral versions use 2 tbsp maple or honey (about 30 g sugar); 1 tsp plus the salt and vanilla is enough once your taste adjusts.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#5A3424", "c": []}, "source_id": "s16", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Tiramisu skyr mousse', 'Tiramisu-skyr', 'Skyr and Greek yogurt replace mascarpone and cream, so the dessert becomes a protein snack with live cultures. Espresso and cocoa bring polyphenols and big flavour with almost no added sugar.', 'snack', array['250 g skyr', '100 g Greek yogurt', '1 shot espresso, cooled', '1 tsp maple syrup', '20 g oats, toasted', '1 tbsp cocoa to dust', 'A little grated 85% chocolate', 'Vanilla']::text[], array['Whisk skyr, Greek yogurt, vanilla and maple syrup until fluffy.', 'Toast the oats in a dry pan and divide between 2 glasses. Spoon over the espresso so it soaks in.', 'Layer the skyr cream on top, dust thickly with cocoa and grate over a little chocolate. Chill 20 minutes.']::text[], 10, 2, 214, 19, 19, 7, array['meal-prep']::text[], '{"why": "Skyr and Greek yogurt replace mascarpone and cream, so the dessert becomes a protein snack with live cultures. Espresso and cocoa bring polyphenols and big flavour with almost no added sugar.", "highlights": ["Live cultures", "Coffee polyphenols", "Dessert swap"], "tip": "All the flavour of tiramisu with no mascarpone, sugar or biscuits.", "fodmap_note": null, "serving_note": null, "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#E9DCC6", "c": []}, "source_id": "s17", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chocolate peanut butter protein pudding', 'Súkkulaði- og hnetusmjörsbúðingur', 'Peanut butter adds healthy fats and makes it more filling, and banana provides gentle natural sweetness. Kotasæla and skyr together give a pudding with real staying power.', 'snack', array['250 g kotasæla', '100 g skyr', '2 tbsp cocoa', '1 heaped tbsp peanut butter (100% peanuts)', '½ small firm banana', 'Pinch of flaky salt, vanilla']::text[], array['Blend everything until silky smooth.', 'Divide into 2 jars and chill 30 minutes. Finish with a pinch of flaky salt.']::text[], 5, 2, 257, 25, 19, 11, array['meal-prep']::text[], '{"why": "Peanut butter adds healthy fats and makes it more filling, and banana provides gentle natural sweetness. Kotasæla and skyr together give a pudding with real staying power.", "highlights": ["Protein + healthy fat", "Cocoa", "Natural sweetness"], "tip": "Banana and peanut butter sweeten it naturally. The salt makes the chocolate taste sweeter.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "jar", "base": "#5E3A28", "c": [["#C99A5B", "crumble", 0.12]]}, "source_id": "s18", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Cacao chia pudding', 'Kakó-chiagrautur', 'Chia provides fibre and plant omega-3, and its gel slows digestion and blunts blood sugar spikes. Cocoa adds flavanols and magnesium, and raspberries are among the most fibre-rich berries.', 'snack', array['80 g chia seeds', '400 ml lactose-free milk', '300 g skyr', '3 tbsp cocoa', '2 tsp maple syrup', '160 g raspberries', 'Vanilla, pinch of salt, cinnamon']::text[], array['Whisk cocoa into the milk first so it doesn''t clump, then add chia, maple, vanilla, salt and cinnamon.', 'Whisk again after 5 minutes, then stir in the skyr.', 'Divide into 4 jars, top with raspberries and chill at least 3 hours.']::text[], 10, 4, 253, 17, 27, 11, array['meal-prep']::text[], '{"why": "Chia provides fibre and plant omega-3, and its gel slows digestion and blunts blood sugar spikes. Cocoa adds flavanols and magnesium, and raspberries are among the most fibre-rich berries.", "highlights": ["Fibre", "Plant omega-3", "Cocoa flavanols"], "tip": "Tastes like chocolate pudding, works as a snack or a quick breakfast.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "jar", "base": "#6A4330", "c": [["#B0304A", "dots", 0.25]]}, "source_id": "s19", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Frozen chocolate mousse pops', 'Frosnir súkkulaðipinnar', 'An ice lolly built on kotasæla and Greek yogurt, so it delivers protein and calcium instead of sugar and stabilisers. Dark chocolate adds cocoa flavanols.', 'snack', array['450 g kotasæla', '150 g Greek yogurt', '4 tbsp cocoa', '1 tbsp maple syrup', '30 g 85% chocolate, melted (to dip)', 'Vanilla, pinch of salt']::text[], array['Blend kotasæla, yogurt, cocoa, maple, vanilla and salt until completely smooth.', 'Pour into 6 ice-lolly moulds or small cups and freeze 4 hours.', 'Dip the tops in melted chocolate and return to the freezer. Rest 3 minutes before eating.']::text[], 10, 6, 155, 12, 10, 8, array['meal-prep', 'freezer']::text[], '{"why": "An ice lolly built on kotasæla and Greek yogurt, so it delivers protein and calcium instead of sugar and stabilisers. Dark chocolate adds cocoa flavanols.", "highlights": ["Protein treat", "Freezer", "Kid-friendly"], "tip": "A summer ice cream that is mostly protein. Kids won''t know the difference.", "fodmap_note": null, "serving_note": null, "keeps_days": 30, "meal_prep": true, "freezer": true, "uses_prep": [], "makes": [], "illustration": {"v": "board", "c": [["#5A3424", "fillet", 0.5]]}, "source_id": "s20", "source_category": "snack"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Iced skyr protein coffee', 'Ískaffi með skyri', 'Blending skyr into coffee turns a pick-me-up into a protein snack. Protein with caffeine helps you avoid the energy crash that sweet coffee drinks often cause.', 'coffee', array['1 double espresso or 150 ml cold brew', '150 g plain skyr', '150 ml lactose-free milk', 'Ice, cinnamon, a few drops of vanilla']::text[], array['Blend coffee, skyr, milk, vanilla and cinnamon for 20 seconds until frothy.', 'Pour over ice.']::text[], 3, 1, 194, 22, 13, 6, NULL, '{"why": "Blending skyr into coffee turns a pick-me-up into a protein snack. Protein with caffeine helps you avoid the energy crash that sweet coffee drinks often cause.", "highlights": ["22 g protein", "Caffeine", "No powder"], "tip": "The ''proffee'' trend made with real food: no powder, no syrup, about 22 g protein.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#B98A60", "c": []}, "source_id": "s5", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Black coffee, brewed well', 'Svart kaffi', 'Coffee is one of the biggest sources of polyphenols in the Western diet, mainly chlorogenic acids. Moderate intake (about 3–4 cups a day) is linked in large studies to lower risk of type 2 diabetes and liver disease. Caffeine sharpens focus and improves exercise performance.', 'coffee', array['18 g freshly ground coffee + 300 ml water at 92–96 °C']::text[], array['Grind just before brewing: medium-fine for pour-over or aeropress, coarse for a French press.', 'Use water just off the boil (92–96 °C) and about 60 g coffee per litre.', 'Pour-over: bloom with a splash of water for 30 seconds, then pour slowly in circles. Total time 3–4 minutes.']::text[], 5, 1, 5, 1, 0, 0, NULL, '{"why": "Coffee is one of the biggest sources of polyphenols in the Western diet, mainly chlorogenic acids. Moderate intake (about 3–4 cups a day) is linked in large studies to lower risk of type 2 diabetes and liver disease. Caffeine sharpens focus and improves exercise performance.", "highlights": ["Polyphenols", "Near zero kcal", "Focus"], "tip": "Good beans brewed right taste naturally sweet and need no sugar. Keep the last cup before about 14:00 to protect sleep.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#2A1A12", "c": []}, "source_id": "c1", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Espresso or americano', 'Espressó eða ameríkanó', 'A double espresso about 30–60 minutes before training is a well-documented way to improve endurance and strength output. Black, it has almost no calories.', 'coffee', array['1 double espresso (≈18 g coffee), plus hot water for an americano']::text[], array['Pull a double espresso in 25–30 seconds.', 'Drink as is, or top with 150 ml hot water for an americano.']::text[], 2, 1, 1, 0, 0, 0, NULL, '{"why": "A double espresso about 30–60 minutes before training is a well-documented way to improve endurance and strength output. Black, it has almost no calories.", "highlights": ["Pre-workout", "Near zero kcal", "Polyphenols"], "tip": "Under 5 kcal. If you want it smoother without sugar, add a pinch of cinnamon or a drop of vanilla.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#3A2416", "c": [["#B07A4A", "smooth", 0.12]]}, "source_id": "c2", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Flat white', 'Flat white', 'Steamed whole milk tastes sweet on its own because heating brings out its natural milk sugar, so no syrup is needed. It adds calcium, iodine and around 5 g of protein.', 'coffee', array['1 double espresso', '150 ml lactose-free whole milk, steamed']::text[], array['Pull a double espresso into a small cup.', 'Steam the milk to about 60 °C with a silky microfoam (no big bubbles).', 'Pour into the centre of the espresso from close range.']::text[], 4, 1, 97, 5, 7, 6, NULL, '{"why": "Steamed whole milk tastes sweet on its own because heating brings out its natural milk sugar, so no syrup is needed. It adds calcium, iodine and around 5 g of protein.", "highlights": ["Calcium", "Natural sweetness", "Moderate protein"], "tip": "Whole milk makes it naturally sweet and creamy; no syrup needed. A cortado is the same drink with less milk.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#C69C72", "c": [["#F4EADA", "smooth", 0.14]]}, "source_id": "c3", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Hot skyr protein latte', 'Heitt prótein-latte', 'Skyr turns a latte into a real protein snack. Cardamom and cinnamon add sweetness without sugar, and cinnamon may slightly improve blood sugar control.', 'coffee', array['1 double espresso', '200 ml lactose-free milk', '100 g skyr, room temperature', 'Cinnamon or cardamom, vanilla']::text[], array['Heat the milk until steaming but not boiling (about 65 °C).', 'Blend or froth the hot milk with skyr and spices for 15 seconds until foamy. Skyr can split if it boils, so keep it below a simmer.', 'Pour over the espresso and dust with cinnamon.']::text[], 5, 1, 192, 18, 13, 8, NULL, '{"why": "Skyr turns a latte into a real protein snack. Cardamom and cinnamon add sweetness without sugar, and cinnamon may slightly improve blood sugar control.", "highlights": ["18 g protein", "Calcium", "Warming"], "tip": "A latte with about 18 g protein. Cardamom gives it a Nordic, almost sweet taste with no sugar.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#CFAE88", "c": [["#F4EADA", "smooth", 0.16]]}, "source_id": "c4", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Protein mocha', 'Prótein-mokka', 'Coffee and cocoa together bring two of the richest sources of dietary polyphenols. Kotasæla makes it creamy and filling, unlike café mochas, which can contain 30–40 g of sugar.', 'coffee', array['1 double espresso', '200 ml lactose-free milk', '100 g kotasæla', '1 tbsp cocoa', '1 scant tsp maple syrup', 'Pinch of salt, vanilla; ice for the iced version']::text[], array['Blend espresso, milk, kotasæla, cocoa, maple, salt and vanilla until completely smooth.', 'Hot: warm gently in a pan to about 65 °C. Iced: pour over ice.', 'Dust with cocoa.']::text[], 5, 1, 258, 21, 21, 13, NULL, '{"why": "Coffee and cocoa together bring two of the richest sources of dietary polyphenols. Kotasæla makes it creamy and filling, unlike café mochas, which can contain 30–40 g of sugar.", "highlights": ["21 g protein", "Cocoa + coffee", "Low sugar"], "tip": "Chocolate and coffee with about 21 g protein. Blending kotasæla makes it silky, like a milkshake.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#6B4430", "c": [["#E8D8C2", "smooth", 0.12]]}, "source_id": "c5", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Cold brew with protein cold foam', 'Kalt kaffi með próteinfroðu', 'Cold brew is smoother and less acidic than hot coffee, which many people find easier on the stomach. The skyr foam replaces syrup-sweetened cream with protein.', 'coffee', array['200 ml cold brew (steeped overnight in the fridge)', '80 g skyr', '60 ml lactose-free milk', '½ tsp maple syrup', 'Vanilla, ice']::text[], array['Cold brew: stir 100 g coarse coffee into 1 L cold water and steep 12–16 hours in the fridge, then strain. Keeps a week.', 'Froth skyr, milk, vanilla and maple with a milk frother or blender for 30 seconds until thick and pourable.', 'Pour cold brew over ice and spoon the foam on top.']::text[], 5, 1, 103, 11, 9, 3, NULL, '{"why": "Cold brew is smoother and less acidic than hot coffee, which many people find easier on the stomach. The skyr foam replaces syrup-sweetened cream with protein.", "highlights": ["11 g protein", "Smooth & low acid", "No syrup"], "tip": "The café ''sweet cream cold foam'' rebuilt with skyr: thick, creamy and about 11 g protein instead of syrup.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "glass", "base": "#3C2618", "c": []}, "source_id": "c6", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Skyr affogato', 'Skyr-affogato', 'A real dessert experience built on frozen skyr, so you finish dinner with about 17 g of protein instead of sugar. Consider decaf espresso in the evening.', 'coffee', array['150 g frozen vanilla skyr scoop (skyr + vanilla, frozen 1 hour)', '1 hot espresso', 'A few shavings of 85% chocolate']::text[], array['Mix skyr with vanilla and freeze in a small bowl for 1 hour until scoopable (or make a batch and soften 10 minutes before serving).', 'Scoop into a glass and pour the hot espresso over it at the table.', 'Finish with chocolate shavings.']::text[], 3, 1, 125, 17, 8, 3, NULL, '{"why": "A real dessert experience built on frozen skyr, so you finish dinner with about 17 g of protein instead of sugar. Consider decaf espresso in the evening.", "highlights": ["Protein dessert", "After dinner", "No sugar"], "tip": "The Italian dessert as an after-dinner protein treat with no sugar.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#F2ECE0", "c": [["#6B4430", "smooth", 0.25]]}, "source_id": "c7", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Butter coffee', 'Smjörkaffi', 'Butter adds fat that slows the release of caffeine and keeps you full for a while. It has no protein, though, so the Lifeline way is to drink it alongside eggs or skyr rather than as a meal replacement.', 'coffee', array['250 ml freshly brewed black coffee', '10 g Icelandic grass-fed butter', 'Optional: cinnamon']::text[], array['Blend hot coffee with butter for 20 seconds until it froths like a latte.']::text[], 3, 1, 77, 1, 0, 8, NULL, '{"why": "Butter adds fat that slows the release of caffeine and keeps you full for a while. It has no protein, though, so the Lifeline way is to drink it alongside eggs or skyr rather than as a meal replacement.", "highlights": ["Satiating fat", "Creamy", "No protein"], "tip": "Popular in biohacking circles. It is filling and creamy but has no protein, so drink it with a protein breakfast rather than instead of one. Keep it to 10 g of butter.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#A57A50", "c": [["#F2D56B", "smooth", 0.1]]}, "source_id": "c8", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Protein hot cocoa', 'Prótein-kakó', 'Cocoa provides magnesium and flavanols, and warm milk with skyr gives protein and calcium. Without caffeine, it is a good evening drink that won''t disturb sleep.', 'coffee', array['250 ml lactose-free milk', '80 g skyr', '1½ tbsp cocoa', '1 scant tsp maple syrup', 'Pinch of salt, cinnamon, vanilla']::text[], array['Whisk cocoa with a splash of milk to a paste, then add the rest of the milk and heat to about 65 °C.', 'Blend or froth in the skyr, maple, salt and vanilla until foamy. Don''t let it boil.']::text[], 5, 1, 246, 19, 24, 11, NULL, '{"why": "Cocoa provides magnesium and flavanols, and warm milk with skyr gives protein and calcium. Without caffeine, it is a good evening drink that won''t disturb sleep.", "highlights": ["Caffeine-free", "19 g protein", "Magnesium"], "tip": "Caffeine-free, so it''s the evening alternative. Icelandic ''kakó'' with about 19 g protein.", "fodmap_note": null, "serving_note": null, "keeps_days": null, "meal_prep": false, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "cup", "base": "#7A4A32", "c": [["#E8D8C2", "smooth", 0.1]]}, "source_id": "c9", "source_category": "coffee"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Argentinian chicken box', 'Argentínubox', 'The same satisfying mix of chicken, rice, egg and avocado, with the fats coming from olive oil, avocado and eggs instead of seed-oil mayo. Skyr sauces replace mayonnaise, adding protein and live cultures while cutting omega-6 oils, which many people over-consume.', 'lunch', array['600 g boneless chicken thighs', 'Chimichurri marinade: 1½ tbsp olive oil, parsley, oregano, smoked paprika, lemon, salt', '2 tsp avocado oil for searing', '240 g white rice (dry)', '4 eggs, soft- or hard-boiled', '2 small avocados', 'Cucumber', 'Spring onion greens (instead of onion)', 'Baked corn chips (see Sauces & toppings)', '(oil for the chips)', 'Sweet chili skyr and garlic skyr sauce, 60 g per box']::text[], array['Marinate the chicken in olive oil, chopped parsley, oregano, smoked paprika, lemon and salt for 30 minutes or overnight.', 'Sear in avocado oil 5–6 minutes per side until 75 °C inside. Rest and slice.', 'Cook the rice and boil the eggs.', 'Box: rice, chicken, egg, cucumber and spring onion greens. Add avocado, corn chips and the two sauces on the day.']::text[], 40, 4, 744, 50, 64, 32, array['meal-prep', 'box']::text[], '{"why": "The same satisfying mix of chicken, rice, egg and avocado, with the fats coming from olive oil, avocado and eggs instead of seed-oil mayo. Skyr sauces replace mayonnaise, adding protein and live cultures while cutting omega-6 oils, which many people over-consume.", "highlights": ["Clean sauces", "Healthy fats", "Choline"], "tip": "The best-selling box made clean: olive-oil chimichurri on the chicken, skyr sauces instead of mayo, and baked corn chips instead of fried nachos.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["q1", "q2", "q7"], "makes": [], "illustration": {"v": "box", "c": [["#B9763E", "strands", 0.25], ["#F4F1E8", "dots", 0.2], ["#F6F1E4", "wedge", 0.15], ["#8DB255", "slices", 0.15], ["#E3C46E", "slices", 0.1]]}, "source_id": "x1", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Mexican chicken box', 'Mexíkóbox', 'Fresh salsa, peppers and pineapple pack vitamin C, which helps absorb iron, and avocado provides monounsaturated fat. Baked corn chips and chipotle skyr replace fried nachos and an oily sauce.', 'lunch', array['600 g boneless chicken thighs', '1 tbsp avocado oil', '240 g white rice (dry)', '2 small avocados', '2 peppers', '160 g fresh pineapple (instead of mango)', 'Fresh salsa: tomato, coriander, lime, chili', 'Lime', 'Baked corn chips (see Sauces & toppings)', '(oil for the chips)', 'Chipotle skyr sauce, 50 g per box', 'Cumin, smoked paprika, oregano, chili, salt']::text[], array['Toss the chicken with avocado oil, cumin, paprika, oregano, chili and salt. Roast at 220 °C for 20–22 minutes.', 'Cook the rice. Chop tomato, coriander, lime and chili into a salsa.', 'Box rice, sliced chicken, pepper, pineapple and salsa. Add avocado, corn chips and chipotle skyr on the day.']::text[], 40, 4, 656, 42, 72, 23, array['meal-prep', 'box']::text[], '{"why": "Fresh salsa, peppers and pineapple pack vitamin C, which helps absorb iron, and avocado provides monounsaturated fat. Baked corn chips and chipotle skyr replace fried nachos and an oily sauce.", "highlights": ["Vitamin C", "Healthy fats", "Low FODMAP swaps"], "tip": "Mango is high in fructose, a common bloating trigger, so pineapple takes its place. A small amount of mango (about 40 g) is fine if you tolerate it.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["q3", "q7"], "makes": [], "illustration": {"v": "box", "c": [["#B8642E", "strands", 0.25], ["#F4F1E8", "dots", 0.2], ["#8DB255", "slices", 0.15], ["#F2C94C", "cubes", 0.12], ["#D6493A", "cubes", 0.12]]}, "source_id": "x2", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Mustard chicken & sweet potato box', 'Sinnepsbox', 'Sweet potato and carrots are among the richest sources of beta-carotene. A mustard glaze gives big flavour for almost no calories, and the sweet chili skyr replaces mayo with protein.', 'lunch', array['600 g boneless chicken thighs', '2 tbsp Dijon + 1 tbsp wholegrain mustard', '1 tsp maple syrup', 'Avocado oil for chicken and sweet potato', '600 g sweet potato, cubed', '2 carrots, ribboned', '2 peppers', '120 g pineapple', 'Salad leaves', 'Baked corn chips (see Sauces & toppings)', 'Sweet chili skyr, 50 g per box']::text[], array['Coat the chicken in mustard, maple, half the oil and salt. Roast at 210 °C for 22 minutes.', 'Roast the sweet potato in the remaining oil on a second tray for 25–30 minutes.', 'Box sweet potato, chicken, carrot, pepper, pineapple and greens. Sweet chili skyr and corn chips on the side.']::text[], 45, 4, 512, 39, 54, 16, array['meal-prep', 'box']::text[], '{"why": "Sweet potato and carrots are among the richest sources of beta-carotene. A mustard glaze gives big flavour for almost no calories, and the sweet chili skyr replaces mayo with protein.", "highlights": ["Vitamin A", "Low sugar", "Gut-friendly"], "tip": "Mustard is one of the best clean flavour bombs: almost no calories, and the honey-mustard taste comes from just one teaspoon of maple.", "fodmap_note": null, "serving_note": null, "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": ["q1", "q7"], "makes": [], "illustration": {"v": "box", "c": [["#C99A3B", "strands", 0.25], ["#E07A2F", "cubes", 0.25], ["#E58A2E", "strands", 0.12], ["#D6493A", "slices", 0.1], ["#F2C94C", "cubes", 0.1]]}, "source_id": "x3", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Asian ginger chicken noodle box', 'Asískt box', 'Rice noodles are naturally wheat-free and gentle on the gut, ginger supports digestion, and broccoli supplies sulforaphane and vitamin C. Peanuts add crunch, protein and healthy fat.', 'lunch', array['600 g boneless chicken thighs', '2 tbsp tamari', '1 tbsp ginger', '1 tbsp avocado oil', '200 g rice noodles (rice + water only)', 'Broccoli florets', 'Cucumber', '120 g pineapple', '40 g roasted peanuts', 'Sweet chili skyr, 40 g per box', 'Spring onion greens, coriander, lime, chili']::text[], array['Marinate chicken in tamari and ginger. Stir-fry in avocado oil over high heat until golden, 8–10 minutes.', 'Soak or boil the rice noodles per the pack, rinse in cold water and toss with a little tamari.', 'Steam broccoli 3 minutes.', 'Box noodles, chicken, broccoli, cucumber and pineapple. Top with peanuts, herbs, lime and sweet chili skyr.']::text[], 30, 4, 548, 42, 55, 18, array['meal-prep', 'box']::text[], '{"why": "Rice noodles are naturally wheat-free and gentle on the gut, ginger supports digestion, and broccoli supplies sulforaphane and vitamin C. Peanuts add crunch, protein and healthy fat.", "highlights": ["Ginger", "Low FODMAP", "Sulforaphane"], "tip": "Rice noodles are naturally wheat-free and low FODMAP. Avocado oil replaces sesame oil.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["q1"], "makes": [], "illustration": {"v": "box", "c": [["#E9DDBA", "strands", 0.3], ["#B8763E", "chunks", 0.25], ["#2F6E35", "leaves", 0.15], ["#93B957", "slices", 0.1], ["#B07A4A", "crumble", 0.06]]}, "source_id": "x4", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Garlic chili chicken pasta box', 'Hvítlauksbox', 'Infusing oil with garlic and removing it gives full garlic flavour with very few fructans, which only dissolve in water. Sourdough croutons in olive oil and a skyr garlic sauce replace fried croutons and mayo-based sauce.', 'lunch', array['600 g boneless chicken thighs', 'Garlic-chili oil: 1½ tbsp avocado oil warmed with 2 sliced garlic cloves (removed) and chili', '240 g pasta (rice pasta for sensitive guts)', '2 peppers', '120 g pineapple', 'Spring onion greens (instead of red onion)', 'Sourdough croutons', '(olive oil for croutons)', 'Garlic skyr sauce, 50 g per box', 'Rocket']::text[], array['Warm the avocado oil gently with sliced garlic and chili for 3 minutes, then lift out the garlic. You keep the flavour without the fructans.', 'Toss the chicken in half the garlic oil with salt and roast at 220 °C for 20 minutes.', 'Cook the pasta and toss with the remaining garlic oil.', 'Box pasta, chicken, pepper, pineapple, spring onion greens and rocket. Croutons and garlic skyr on the side.']::text[], 35, 4, 577, 41, 64, 17, array['meal-prep', 'box']::text[], '{"why": "Infusing oil with garlic and removing it gives full garlic flavour with very few fructans, which only dissolve in water. Sourdough croutons in olive oil and a skyr garlic sauce replace fried croutons and mayo-based sauce.", "highlights": ["Garlic flavour, gentler", "Clean croutons", "Satisfying"], "tip": "Dates are left out: they are high in sugar and fructans. Pineapple brings the sweet note instead.", "fodmap_note": "Regular wheat pasta is high in fructans; use rice or corn pasta for a gentler version.", "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["q2", "q8"], "makes": [], "illustration": {"v": "box", "c": [["#E8D6A0", "strands", 0.3], ["#C2783A", "chunks", 0.25], ["#D6493A", "slices", 0.12], ["#F2C94C", "cubes", 0.1], ["#C99A5B", "cubes", 0.08]]}, "source_id": "x5", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Italian pesto chicken box', 'Ítalskt box', 'Homemade pesto made with extra-virgin olive oil delivers polyphenols, which are linked to lower inflammation. Tomatoes, olives, feta and sweet potato make a classic Mediterranean plate.', 'lunch', array['600 g boneless chicken thighs', 'Pesto: basil, 40 g olive oil, 30 g parmesan, 20 g pumpkin seeds, lemon, ½ garlic clove', '(parmesan for the pesto)', '(pumpkin seeds for the pesto)', '(a big bunch of basil)', '500 g sweet potato', 'Avocado oil for roasting', 'Olives', 'Cherry tomatoes', '80 g feta', '100 g grapes', 'Sourdough croutons', 'Basil yogurt sauce, 30 g per box']::text[], array['Blend basil, olive oil, parmesan, pumpkin seeds, lemon, garlic and salt into a pesto. Coat the chicken with half.', 'Roast chicken at 210 °C for 22 minutes and sweet potato cubes in avocado oil for 25–30 minutes.', 'Box sweet potato, sliced chicken, tomatoes, olives, feta and grapes. Spoon over the rest of the pesto.', 'Croutons and basil yogurt sauce on the side.']::text[], 45, 4, 658, 42, 43, 36, array['meal-prep', 'box']::text[], '{"why": "Homemade pesto made with extra-virgin olive oil delivers polyphenols, which are linked to lower inflammation. Tomatoes, olives, feta and sweet potato make a classic Mediterranean plate.", "highlights": ["Polyphenols", "Mediterranean", "Vitamin A"], "tip": "Most jarred pesto is made with sunflower oil and cashews. Homemade with olive oil and pumpkin seeds is seed-oil free and low FODMAP.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["q4", "q5", "q8"], "makes": [], "illustration": {"v": "box", "c": [["#7E9A3E", "chunks", 0.25], ["#E07A2F", "cubes", 0.2], ["#D6493A", "balls", 0.15], ["#F4F3EE", "crumble", 0.1], ["#4A3A3A", "balls", 0.06], ["#8A5A8A", "balls", 0.08]]}, "source_id": "x6", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chicken Caesar box', 'Sesarsalatbox', 'A skyr Caesar dressing keeps the anchovy and parmesan flavour while turning the sauce into a protein source. Eggs add choline and parmesan adds calcium.', 'lunch', array['600 g chicken thighs (or breast)', '2 tsp avocado oil', '2 heads romaine', '4 eggs', 'Tomatoes', 'Olives', '60 g parmesan (40 shaved, 20 in dressing)', 'Sourdough croutons', 'Olive oil (croutons + dressing)', 'Caesar dressing: 150 g skyr, lemon, Dijon, 2 anchovies, ½ garlic clove, black pepper', '(Dijon)']::text[], array['Season and sear the chicken in avocado oil until 75 °C inside. Slice.', 'Croutons: cube the sourdough, toss in olive oil and bake at 200 °C for 8–10 minutes.', 'Dressing: blend skyr, 20 g parmesan, lemon, mustard, anchovies, garlic, a little olive oil and pepper.', 'Box lettuce, chicken, halved eggs, tomatoes and olives. Dressing, croutons and shaved parmesan on the side.']::text[], 30, 4, 536, 50, 18, 29, array['meal-prep', 'box']::text[], '{"why": "A skyr Caesar dressing keeps the anchovy and parmesan flavour while turning the sauce into a protein source. Eggs add choline and parmesan adds calcium.", "highlights": ["Protein-rich dressing", "Choline", "Calcium"], "tip": "Classic Caesar dressing is an oil emulsion. The skyr version keeps the anchovy-parmesan punch and adds 10 g protein per box.", "fodmap_note": null, "serving_note": null, "keeps_days": 3, "meal_prep": true, "freezer": false, "uses_prep": ["p2", "q8"], "makes": [], "illustration": {"v": "box", "c": [["#9BBE5E", "leaves", 0.3], ["#C99A5B", "strands", 0.2], ["#F6F1E4", "wedge", 0.15], ["#D6493A", "balls", 0.1], ["#C99A5B", "cubes", 0.08]]}, "source_id": "x7", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('BBQ chicken wrap', 'BBQ-vefja', 'BBQ flavour without the sugar load of shop sauce: tomato paste brings lycopene and smoked paprika the depth. A cottage cheese wrap pushes protein even higher.', 'lunch', array['600 g boneless chicken thighs', '2 tsp avocado oil', 'Clean BBQ sauce, about 2 tbsp per wrap (see Sauces & toppings)', '(maple in the BBQ sauce)', '4 large homemade wraps, or cottage cheese wraps for more protein', '80 g grated cheese', 'Tomato', 'Pineapple (instead of mango)', 'Lettuce', 'Garlic skyr sauce']::text[], array['Roast the chicken at 220 °C for 20 minutes, then brush with BBQ sauce and grill 3 minutes until sticky.', 'Slice and fill the warm wraps with lettuce, tomato, pineapple, cheese, chicken, garlic skyr and a little more BBQ sauce.', 'Roll tightly and wrap in baking paper.']::text[], 35, 4, 524, 43, 38, 22, array['meal-prep', 'box']::text[], '{"why": "BBQ flavour without the sugar load of shop sauce: tomato paste brings lycopene and smoked paprika the depth. A cottage cheese wrap pushes protein even higher.", "highlights": ["Low sugar BBQ", "High protein", "Family favourite"], "tip": "Shop BBQ sauce is often 30–50% sugar. The Lifeline version gets its smoky sweetness from tomato paste, smoked paprika and a teaspoon of maple.", "fodmap_note": null, "serving_note": "1 large wrap", "keeps_days": 2, "meal_prep": true, "freezer": false, "uses_prep": ["q6", "q2"], "makes": [], "illustration": {"v": "board", "c": [["#E2C9A0", "slices", 0.35], ["#8A3B26", "strands", 0.25], ["#F2C94C", "cubes", 0.1], ["#6E9E3E", "leaves", 0.12]]}, "source_id": "x8", "source_category": "box"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sweet chili skyr', 'Sæt chilísósa með skyri', 'A sauce that adds about 3 g of protein per spoon instead of 10 g of oil. The chili and lime make it taste far richer than its calories.', 'sauce', array['250 g skyr', '2 tsp maple syrup', 'Juice of 1 lime', 'A small piece of garlic, grated', '1 tsp chili flakes, ½ tsp smoked paprika, salt']::text[], array['Stir everything together and leave 10 minutes for the chili to bloom.', 'Keep in a jar in the fridge.']::text[], 5, 8, 24, 3, 2, 0, array['meal-prep']::text[], '{"why": "A sauce that adds about 3 g of protein per spoon instead of 10 g of oil. The chili and lime make it taste far richer than its calories.", "highlights": ["Protein sauce", "No seed oil", "Low sugar"], "tip": "Replaces sweet chilli mayo. Shop versions are typically rapeseed oil, sugar and stabilisers; this is protein with a gentle sweet heat.", "fodmap_note": null, "serving_note": "2 tbsp (30 g)", "keeps_days": 5, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F2D9C8", "c": [["#C8402E", "crumble", 0.1]]}, "source_id": "q1", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Garlic skyr sauce', 'Hvítlaukssósa', 'Yogurt and skyr provide live cultures and protein. Use garlic-infused oil instead of raw garlic for a fully low-FODMAP version.', 'sauce', array['150 g skyr', '100 g Greek yogurt', '1 small garlic clove, grated (or 1 tbsp garlic-infused oil)', 'Lemon', '2 tsp olive oil', 'Chives, parsley, salt']::text[], array['Stir everything together and season well with salt.', 'Rest 15 minutes for the garlic to mellow.']::text[], 5, 8, 40, 3, 2, 2, array['meal-prep']::text[], '{"why": "Yogurt and skyr provide live cultures and protein. Use garlic-infused oil instead of raw garlic for a fully low-FODMAP version.", "highlights": ["Live cultures", "No mayo", "Low FODMAP option"], "tip": "The Icelandic ''hvítlaukssósa'' made with skyr and yogurt instead of mayonnaise.", "fodmap_note": null, "serving_note": "2 tbsp (30 g)", "keeps_days": 5, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#F4F1E8", "c": [["#6E9E3E", "crumble", 0.08]]}, "source_id": "q2", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Chipotle skyr sauce', 'Chipotlesósa', 'Smoked chili gives depth and a little capsaicin, which may slightly boost metabolism. Skyr makes it creamy with protein instead of oil.', 'sauce', array['250 g skyr', '2 tsp tomato paste', 'Lime', '½ tsp maple syrup', '1–2 tsp chipotle powder or smoked paprika + chili, salt']::text[], array['Stir everything together until evenly orange. Taste and adjust the heat.']::text[], 5, 8, 22, 3, 2, 0, array['meal-prep']::text[], '{"why": "Smoked chili gives depth and a little capsaicin, which may slightly boost metabolism. Skyr makes it creamy with protein instead of oil.", "highlights": ["Smoky", "Protein sauce", "No seed oil"], "tip": "Smoky and creamy with none of the oil of a shop chipotle mayo.", "fodmap_note": null, "serving_note": "2 tbsp (30 g)", "keeps_days": 5, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#E3A47A", "c": []}, "source_id": "q3", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Olive oil pesto', 'Pestó', 'Extra-virgin olive oil is rich in polyphenols such as oleocanthal, which has anti-inflammatory effects. Basil adds vitamin K and antioxidants, and pumpkin seeds add zinc and magnesium.', 'sauce', array['1 large bunch basil', '80 ml extra-virgin olive oil', '40 g parmesan', '30 g pumpkin seeds, toasted', 'Lemon', 'A small piece of garlic', 'Salt']::text[], array['Blend basil, pumpkin seeds, parmesan, garlic and lemon, then stream in the olive oil.', 'Store in a jar with a thin layer of oil on top to keep it green.']::text[], 5, 8, 131, 3, 1, 13, array['meal-prep']::text[], '{"why": "Extra-virgin olive oil is rich in polyphenols such as oleocanthal, which has anti-inflammatory effects. Basil adds vitamin K and antioxidants, and pumpkin seeds add zinc and magnesium.", "highlights": ["Polyphenols", "Healthy fats", "No sunflower oil"], "tip": "Pumpkin seeds replace pine nuts and cashews, and real olive oil replaces sunflower oil.", "fodmap_note": null, "serving_note": "1 tbsp (20 g)", "keeps_days": 7, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#5E7E2E", "c": [["#F1E7C9", "crumble", 0.08]]}, "source_id": "q4", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Basil yogurt sauce', 'Basilíkusósa', 'A creamy herb sauce built on Greek yogurt, so it adds protein and live cultures rather than oil.', 'sauce', array['200 g Greek yogurt', 'Handful of basil', 'Lemon', '2 tsp olive oil', 'Salt, pepper']::text[], array['Blend everything until smooth and pale green.']::text[], 5, 8, 44, 2, 1, 4, array['meal-prep']::text[], '{"why": "A creamy herb sauce built on Greek yogurt, so it adds protein and live cultures rather than oil.", "highlights": ["Live cultures", "Fresh herbs", "Light"], "tip": "A fresh, creamy dressing for the Italian box and roasted vegetables.", "fodmap_note": null, "serving_note": "2 tbsp (30 g)", "keeps_days": 4, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#DCE6C4", "c": []}, "source_id": "q5", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Clean BBQ sauce', 'BBQ-sósa án sykurs', 'Concentrated tomato paste is rich in lycopene, and smoked paprika adds depth without the need for sugar or liquid smoke.', 'sauce', array['1 tin tomato paste', '200 g canned tomatoes', '1 tbsp Dijon', '1 tbsp maple syrup', '1 tbsp tamari', '1 tbsp cider vinegar or lemon', '2 tsp smoked paprika, 1 tsp cumin, pinch of chili, pinch of salt']::text[], array['Simmer everything for 10 minutes, stirring, until thick and glossy.', 'Blend smooth if you like. Keeps 2 weeks in a jar.']::text[], 15, 10, 23, 1, 5, 0, array['meal-prep']::text[], '{"why": "Concentrated tomato paste is rich in lycopene, and smoked paprika adds depth without the need for sugar or liquid smoke.", "highlights": ["Low sugar", "Lycopene", "No additives"], "tip": "About 4 g sugar per serving, against 10–15 g in most shop BBQ sauces.", "fodmap_note": null, "serving_note": "2 tbsp (35 g)", "keeps_days": 14, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "base": "#7A2A1E", "c": []}, "source_id": "q6", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Baked corn chips', 'Ofnbakaðar maísflögur', 'Baking instead of frying cuts the oil to a fraction, and you choose the oil. Corn tortillas are low FODMAP and gluten-free.', 'sauce', array['9 corn tortillas (150 g masa harina), see Wraps', '1 tbsp avocado oil', 'Flaky salt, smoked paprika, lime zest']::text[], array['Brush the tortillas lightly with avocado oil and cut each into 8 triangles.', 'Spread on trays and bake at 190 °C for 8–12 minutes until crisp, turning once.', 'Season with salt, paprika and lime zest. Cool and keep in an airtight tin.']::text[], 25, 6, 113, 2, 19, 4, array['meal-prep']::text[], '{"why": "Baking instead of frying cuts the oil to a fraction, and you choose the oil. Corn tortillas are low FODMAP and gluten-free.", "highlights": ["Baked not fried", "Wheat-free", "Low FODMAP"], "tip": "Shop nachos are fried, usually in sunflower or palm oil. These are baked with a tablespoon of avocado oil.", "fodmap_note": null, "serving_note": "25 g", "keeps_days": 7, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#E3C46E", "chunks", 0.7]]}, "source_id": "q7", "source_category": "sauce"}'::jsonb, false, false);
insert into meals (name, name_is, description, category, ingredients, instructions, prep_time_min, servings, calories, protein, carbs, fat, dietary_tags, curated, retired, is_filler) values ('Sourdough croutons', 'Brauðteningar', 'Homemade croutons use olive oil and your own sourdough, avoiding the seed oils, flavourings and preservatives in shop croutons.', 'sauce', array['160 g day-old sourdough', '1 tbsp olive oil', 'Salt, dried oregano']::text[], array['Cube the bread, toss with olive oil, salt and oregano.', 'Bake at 200 °C for 8–10 minutes until golden. Cool and store airtight.']::text[], 15, 8, 67, 2, 10, 2, array['meal-prep']::text[], '{"why": "Homemade croutons use olive oil and your own sourdough, avoiding the seed oils, flavourings and preservatives in shop croutons.", "highlights": ["Olive oil", "No waste", "Crunch"], "tip": "A good way to use up the end of a homemade loaf.", "fodmap_note": null, "serving_note": "20 g", "keeps_days": 7, "meal_prep": true, "freezer": false, "uses_prep": [], "makes": [], "illustration": {"v": "bowl", "c": [["#C99A5B", "cubes", 0.7]]}, "source_id": "q8", "source_category": "sauce"}'::jsonb, false, false);
